/* ── eski dağıtımı temizle: service worker + tarayıcı önbelleği ──
   Kayıtlara DOKUNMAZ: window.storage ayrı bir alandır, CacheStorage değildir. */
async function eskiDagitimiTemizle() {
  let sw = 0, cache = 0;
  try { if (typeof navigator !== "undefined" && navigator.serviceWorker) {
    const rs = await navigator.serviceWorker.getRegistrations();
    for (const r of rs) { try { await r.unregister(); sw++; } catch (e) {} } } } catch (e) {}
  try { if (typeof caches !== "undefined") {
    const ks = await caches.keys();
    for (const k of ks) { try { await caches.delete(k); cache++; } catch (e) {} } } } catch (e) {}
  return { sw, cache, temiz: sw + cache > 0 };
}
async function zorlaYenile() {
  await eskiDagitimiTemizle();
  try { const u = new URL(window.location.href); u.searchParams.set("v", YAPIM_ID + "-" + Date.now()); window.location.replace(u.toString()); }
  catch (e) { window.location.reload(); }
}
