const z2 = (n) => String(n).padStart(2, "0");
const ymd = (d) => `${d.getFullYear()}-${z2(d.getMonth() + 1)}-${z2(d.getDate())}`;
const parseD = (s) => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
const addDays = (s, n) => { const d = parseD(s); d.setDate(d.getDate() + n); return ymd(d); };
const gunFark = (a, b) => Math.round((parseD(a) - parseD(b)) / 86400000);
const haftaGunu = (s) => parseD(s).getDay();            // 0=Pazar
const kisaTarih = (s) => { const d = parseD(s); return `${z2(d.getDate())}.${z2(d.getMonth() + 1)}`; };
const uzunTarih = (s) => parseD(s).toLocaleDateString("tr-TR", { day: "numeric", month: "long", year: "numeric" });
