/* ───────── deterministik RNG ───────── */
function hashStr(str) { let h = 2166136261 >>> 0; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function mulberry32(a) { return function () { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const rngFor = (...parts) => mulberry32(hashStr(parts.join("|")));
const rint = (rng, a, b) => a + Math.floor(rng() * (b - a + 1));
function poisson(l, rng) { l = clamp(l, 0.05, 8); const L = Math.exp(-l); let k = 0, p = 1; do { k++; p *= rng(); } while (p > L); return k - 1; }
const secAgirlikli = (rng, agirliklar) => { const t = agirliklar.reduce((s, x) => s + x, 0); if (t <= 0) return 0; let r = rng() * t; for (let i = 0; i < agirliklar.length; i++) { r -= agirliklar[i]; if (r <= 0) return i; } return agirliklar.length - 1; };

