/* geriye uyum: eski kademe sistemi (1 en üst … 5 en alt) */
const KADEME_LIG = { 5: "tr-3", 4: "tr-2", 3: "tr-1", 2: "en-2", 1: "en-1" };
/* ── LİG ÜYELİĞİ · tek doğruluk kaynağı ──
   Bir kulübün rakipleri KENDİ liginden gelir. Kademe numarası lig belirlemez. */
const ligBulKulup = (ad) => {
  for (const [id, l] of Object.entries(LIGLER)) if ((l.takim || []).includes(ad)) return id;
  return null;
};
function kulupLigi(d) {
  if (!d || !d.kulup) return "tr-3";
  if (d.kulup.lig && LIGLER[d.kulup.lig]) return d.kulup.lig;
  const bul = ligBulKulup(d.kulup.ad);
  return bul || KADEME_LIG[clamp(d.kulup.kademe || 5, 1, 5)] || "tr-3";
}
/* aynı ülkenin ligleri, üstten alta sıralı */
const ulkeLigleri = (ulke) => Object.entries(LIGLER).filter(([, l]) => l.ulke === ulke)
  .sort((a, b) => a[1].kademe - b[1].kademe).map(([id]) => id);
/* terfi/düşmede aynı ülkede komşu lige taşı */
function ligTasi(ligId, yon) {
  const l = LIGLER[ligId]; if (!l) return ligId;
  const zincir = ulkeLigleri(l.ulke);
  const i = zincir.indexOf(ligId);
  if (i < 0) return ligId;
  const j = clamp(i + (yon === "terfi" ? -1 : 1), 0, zincir.length - 1);
  return zincir[j];
}
/* bir ligin rakip listesi — kendi kulübün hariç */
const ligRakipleri = (ligId, hariç) => ((LIGLER[ligId] || {}).takim || []).filter((x) => x !== hariç);
const KADEME_AD = { 5: "TFF 2. Lig", 4: "TFF 1. Lig", 3: "Süper Lig", 2: "Championship", 1: "Premier League" };
const KADEME_BANT = { 5: [52, 62], 4: [60, 70], 3: [66, 76], 2: [72, 84], 1: [80, 92] };
const ligAdi = (id) => (LIGLER[id] ? `${LIGLER[id].ad} · ${ULKELER[LIGLER[id].ulke].ad}` : "");
/* ═══ KULÜP BÜYÜKLÜĞÜ ═══
   Lig itibarı tek başına yetmiyordu: La Liga'dan rastgele seçince Espanyol "en zor teklif"
   olabiliyordu. Artık her kulübün kendi gücü var. Açıkça yazılmayanlar lig içindeki
   sıralarından türetilir (listeler güçlüden zayıfa dizili). */
const KULUP_GUC = {
  /* Avrupa devleri */
  "Real Madrid": 95, "Manchester City": 94, "Bayern München": 93, "Barcelona": 92,
  "Liverpool": 91, "Paris Saint-Germain": 91, "Inter": 90, "Arsenal": 90,
  "Bayer Leverkusen": 88, "Atlético Madrid": 88, "Juventus": 87, "Milan": 87,
  "Borussia Dortmund": 86, "Chelsea": 86, "Napoli": 86, "Tottenham": 84,
  "RB Leipzig": 84, "Manchester United": 84, "Atalanta": 83, "Roma": 82,
  "Aston Villa": 82, "Newcastle": 81, "Benfica": 81, "Porto": 80,
  "Sporting CP": 80, "Marseille": 79, "Lazio": 79, "Villarreal": 78,
  "Monaco": 78, "Ajax": 78, "PSV": 78, "Athletic Bilbao": 78,
  "Real Sociedad": 77, "Lille": 77, "Feyenoord": 77, "Eintracht Frankfurt": 77,
  "Fiorentina": 76, "Real Betis": 76, "Sevilla": 76, "Lyon": 75,
  "Nice": 75, "VfB Stuttgart": 75, "Bologna": 74, "Brighton": 74,
  "West Ham": 74, "Girona": 73, "Valencia": 73, "Braga": 73,
  /* Türkiye */
  "Galatasaray": 80, "Fenerbahçe": 79, "Beşiktaş": 76, "Trabzonspor": 74,
  "Başakşehir": 71, "Adana Demirspor": 69, "Samsunspor": 68, "Konyaspor": 67,
  "Alanyaspor": 67, "Rizespor": 66, "Gaziantep FK": 66, "Kasımpaşa": 65,
};
function kulupGucu(ad, ligId) {
  if (KULUP_GUC[ad] != null) return KULUP_GUC[ad];
  const lid = ligId || ligBulKulup(ad);
  const l = LIGLER[lid];
  if (!l) return 55;
  const tk = l.takim || [];
  /* açık değeri olan kulüpler tavanı belirler; türetilenler onların ALTINA sıkışır */
  const acik = tk.filter((x) => KULUP_GUC[x] != null).map((x) => KULUP_GUC[x]);
  const tavan = acik.length ? Math.min(Math.min(...acik) - 1, l.bant[1]) : l.bant[1];
  const taban = Math.min(l.bant[0], tavan - 1);
  const kalan = tk.filter((x) => KULUP_GUC[x] == null);
  const i = Math.max(0, kalan.indexOf(ad));
  const n = Math.max(1, kalan.length - 1);
  return Math.round(tavan - (tavan - taban) * (i / n));
}
/* tüm dünyadaki kulüpleri güçleriyle listele */
function kulupHavuzu() {
  const out = [];
  for (const [lid, l] of Object.entries(LIGLER))
    for (const ad of (l.takim || [])) out.push({ ad, lig: lid, ligAd: l.ad, ulke: l.ulke,
      itibar: l.itibar, kademe: clamp(6 - l.itibar, 1, 5), guc: kulupGucu(ad, lid) });
  return out.sort((a, b) => b.guc - a.guc);
}
const ligListesi = () => Object.entries(LIGLER).map(([id, l]) => ({ id, ...l }));
/* kademeye karşılık gelen lig havuzu — teklifler artık tüm dünyadan gelir */
function ligBul(kademe) {
  const hedefItibar = [0, 5, 4, 3, 3, 2][kademe] || 3;
  return ligListesi().filter((l) => Math.abs(l.itibar - hedefItibar) <= 1);
}
const STAD_EK = ["Arena", "Stadyumu", "Park", "Stadium", "Sahası"];
function kulupBilgi(ad, ligId) {
  const l = LIGLER[ligId] || LIGLER["tr-3"];
  const h = hashStr(ad);
  const yil = 1880 + (h % 118);
  return { ad, sehir: ad.split(" ")[0], stad: `${ad.split(" ")[0]} ${STAD_EK[h % STAD_EK.length]}`, yil, lig: ligId, ulke: l.ulke };
}
const KULUP_HAVUZ = {
  5: LIGLER["tr-3"].takim.map((a) => { const b = kulupBilgi(a, "tr-3"); return [b.ad, b.sehir, b.stad, b.yil]; }),
  4: LIGLER["tr-2"].takim.map((a) => { const b = kulupBilgi(a, "tr-2"); return [b.ad, b.sehir, b.stad, b.yil]; }),
  3: LIGLER["tr-1"].takim.map((a) => { const b = kulupBilgi(a, "tr-1"); return [b.ad, b.sehir, b.stad, b.yil]; }),
  2: LIGLER["en-2"].takim.map((a) => { const b = kulupBilgi(a, "en-2"); return [b.ad, b.sehir, b.stad, b.yil]; }),
  1: LIGLER["en-1"].takim.map((a) => { const b = kulupBilgi(a, "en-1"); return [b.ad, b.sehir, b.stad, b.yil]; }),
};
const RAKIP_HAVUZ = {
  5: LIGLER["tr-3"].takim, 4: LIGLER["tr-2"].takim, 3: LIGLER["tr-1"].takim,
  2: LIGLER["en-2"].takim, 1: LIGLER["en-1"].takim,
};
function kulupOlustur(kademe, idx, ligId) {
  /* ligId verilirse o ligden bir kulüp seç — ülke tutarlılığı korunur */
  if (ligId && LIGLER[ligId]) {
    const tk = LIGLER[ligId].takim || [];
    const ad2 = tk[Math.abs(idx) % Math.max(1, tk.length)] || tk[0] || "FC";
    const b = kulupBilgi(ad2, ligId);
    return { ad: b.ad, sehir: b.sehir, stad: b.stad, kurulus: b.yil, lig: ligId,
      kademe: clamp(6 - (LIGLER[ligId].itibar || 3), 1, 5), prestij: LIGLER[ligId].itibar || 3,
      hedef: "ilk yarı", yonetimGuveni: 70, butce: Math.round(18 * Math.pow(2.1, (LIGLER[ligId].itibar || 3) - 1)),
      taraftarBeklentisi: LIGLER[ligId].itibar || 3 };
  }
  const h = KULUP_HAVUZ[clamp(kademe, 1, 5)] || KULUP_HAVUZ[5];
  const [ad, sehir, stad, yil] = h[Math.abs(idx) % h.length];
  const hedef = kademe >= 4 ? "kümede kalmak" : kademe === 3 ? "ilk 8" : kademe === 2 ? "Avrupa" : "şampiyonluk";
  return { ad, sehir, kademe, lig: ligBulKulup(ad) || KADEME_LIG[clamp(kademe, 1, 5)], prestij: 6 - kademe, hedef, yonetimGuveni: 70, butce: [4, 12, 40, 90, 220][5 - kademe], taraftarBeklentisi: 6 - kademe, stadAdi: stad, kurulusYili: yil };
}

