function konuKur(d) { return khKur(d); }
function konuKurV69(d) {
  const out = [];
  for (const [ders, v] of Object.entries(MUFREDAT)) {
    const p2 = (d.oyuncular || []).find((x) => x.ad === ders
      || x.ad.toLocaleLowerCase("tr").startsWith(ders.split(" ")[0].toLocaleLowerCase("tr")));
    let sira = 0;
    (v.uniteler || []).forEach((u, ui) => (u.k || []).forEach((k) => {
      out.push({ id: "k" + hashStr(ders + u.en + k[0] + k[1]).toString(36), ders, dersTr: v.tr,
        unite: u.tr, uniteEn: u.en, uniteSira: ui, kod: k[0], ad: k[2], adEn: k[1],
        pid: p2 ? p2.id : null, kademe: "yok", sira: sira++, tekrarSayi: 0, sonDokunma: null, notu: "" });
    }));
  }
  return out;
}
function konuOzet(d, ders) {
  const k = (d.konular || []).filter((x) => !ders || x.ders === ders);
  const say = { yok: 0, islendi: 0, tekrar: 0, oturdu: 0 };
  for (const x of k) say[x.kademe] = (say[x.kademe] || 0) + 1;
  const puan = k.reduce((a, x) => a + KONU_KADEME[x.kademe].puan, 0);
  return { toplam: k.length, say, puan, azami: k.length * 3,
    oran: k.length ? puan / (k.length * 3) : 0, fetih: k.length ? say.oturdu / k.length : 0 };
}
function konuIlerlet(d, id, bugun, geri) {
  const sira = ["yok", "islendi", "tekrar", "oturdu"];
  return { ...d, konular: (d.konular || []).map((x) => {
    if (x.id !== id) return x;
    const i = sira.indexOf(x.kademe);
    const j = clamp(i + (geri ? -1 : 1), 0, 3);
    /* v71 · her kademenin ilk ulaşıldığı gün saklanır: geri alıp yeniden ilerletmek XP'yi ikinci kez yazdırmaz, dokunmak taşımaz */
    const kt = { ...(x.kt && typeof x.kt === "object" ? x.kt : {}) };
    if (!geri) for (let m = 1; m <= j; m++) if (!kt[sira[m]]) kt[sira[m]] = bugun;
    return { ...x, kademe: sira[j], sonDokunma: bugun, kt,
      tekrarSayi: (!geri && sira[j] === "tekrar") ? (x.tekrarSayi || 0) + 1 : x.tekrarSayi || 0 };
  }) };
}

/* ═══════════ KAPALI KİTAP ANLATMA · en güçlü kanıtlı teknik ═══════════
   Adesope 2017: g = 0.61, lisede diğer yaş gruplarından daha etkili.
   Dunlosky'nin "yüksek fayda" verdiği iki teknikten biri. Buradaki amaç tek şey:
   bu tekniği tek dokunuşluk hâle getirmek. Sonunda eksikler doğrudan hata defterine düşer. */
const ANLATMA_ASAMA = [
  { k: "hazir", ad: "Hazır", ac: "Kaynağı kapat. Sadece konu adı önünde." },
  { k: "anlat", ad: "Anlatıyorum", ac: "Boş kâğıda ya da sesli olarak anlat. Bakma." },
  { k: "kontrol", ad: "Kontrol", ac: "Şimdi kaynağı aç ve eksikleri işaretle." },
  { k: "bitti", ad: "Bitti", ac: "Eksikler hata defterine işlendi." },
];
function anlatmaKaydet(d, kayit, bugun) {
  let y = { ...d, anlatmalar: [...(d.anlatmalar || []), {
    id: "an" + Date.now().toString(36), tarih: bugun, konuId: kayit.konuId, ders: kayit.ders,
    konuAd: kayit.konuAd, saniye: kayit.saniye, ozDeger: kayit.ozDeger, eksikler: kayit.eksikler || [] }].slice(-200) };
  /* eksikler otomatik hata defterine girer ve aralıklı tekrara alınır */
  for (const e of (kayit.eksikler || []))
    y = hataEkle(y, { tur: "bilgi", konu: `${kayit.konuAd}: ${e}`, pid: kayit.pid }, bugun);
  /* öz-değerlendirme yüksekse konu kademesi ilerler */
  if (kayit.ozDeger >= 4 && kayit.konuId) y = konuIlerlet(y, kayit.konuId, bugun);
  /* seans olarak da kaydedilir — aktif çalışma sayılır */
  const dk = Math.max(1, Math.round(kayit.saniye / 60));
  y = { ...y, antrenman: { ...y.antrenman, [bugun]: [...(y.antrenman[bugun] || []),
    { id: "anl" + Date.now().toString(36), pid: kayit.pid, dakika: dk, zorluk: 3, tur: "bitiricilik",
      soru: 5, dogru: Math.round(kayit.ozDeger), tahmin: null, saat: new Date().getHours(), anlatma: true }] } };
  return y;
}
function anlatmaOzet(d, bugun) {
  const a = d.anlatmalar || [];
  const son7 = a.filter((x) => gunFark(bugun, x.tarih) <= 7);
  const ortSure = a.length ? Math.round(a.reduce((s, x) => s + x.saniye, 0) / a.length) : 0;
  const ortDeger = a.length ? (a.reduce((s, x) => s + (x.ozDeger || 0), 0) / a.length) : 0;
  return { toplam: a.length, son7: son7.length, ortSure, ortDeger: Math.round(ortDeger * 10) / 10,
    toplamEksik: a.reduce((s, x) => s + (x.eksikler || []).length, 0) };
}

/* ═══════════ DÜNYA MASASI · Global Politics vaka bankası ═══════════
   Global Politics HL Paper 2 ve 3, EE ve Engagement: hepsi GERÇEK vaka gerektirir.
   Genel bir çalışma uygulaması bunu yapamaz — ama senin dersin güncel olayların kendisi.
   UİK toplantı konuları da buradan beslenir. */
const GP_KAVRAM = {
  guc: { ad: "Güç", renk: "kirmizi" }, egemenlik: { ad: "Egemenlik", renk: "mor" },
  mesruiyet: { ad: "Meşruiyet", renk: "amber" }, insanHaklari: { ad: "İnsan hakları", renk: "mavi" },
  kalkinma: { ad: "Kalkınma", renk: "yesil" }, baris: { ad: "Barış ve çatışma", renk: "turuncu" },
  bagimlilik: { ad: "Karşılıklı bağımlılık", renk: "teal" }, adalet: { ad: "Adalet", renk: "limon" },
  esitlik: { ad: "Eşitlik", renk: "mavi" }, kimlik: { ad: "Kimlik", renk: "mor" },
};
const GP_OLCEK = ["yerel", "ulusal", "bölgesel", "küresel"];
function vakaEkle(d, v, bugun) {
  return { ...d, vakalar: [...(d.vakalar || []), {
    id: "v" + Date.now().toString(36), tarih: bugun, baslik: v.baslik, yer: v.yer || "",
    kavramlar: v.kavramlar || [], olcek: v.olcek || "küresel", ozet: v.ozet || "",
    kaynak: v.kaynak || "", kullanim: v.kullanim || [], guclu: !!v.guclu }].slice(-300) };
}
function vakaOzet(d) {
  const v = d.vakalar || [];
  const say = {};
  for (const k of Object.keys(GP_KAVRAM)) say[k] = v.filter((x) => (x.kavramlar || []).includes(k)).length;
  const bos = Object.keys(GP_KAVRAM).filter((k) => say[k] === 0);
  const zayif = Object.keys(GP_KAVRAM).filter((k) => say[k] > 0 && say[k] < 2);
  return { toplam: v.length, say, bos, zayif, guclu: v.filter((x) => x.guclu).length,
    olcek: GP_OLCEK.reduce((a, o) => ({ ...a, [o]: v.filter((x) => x.olcek === o).length }), {}) };
}

/* ═══════════ DİNLEME YÜKÜ · erişilebilirlik katmanı ═══════════
   Beltone Achieve + MyPal uzak mikrofon kullanıyorsun. İşitme cihazı kullanıcılarında
   "dinleme çabası" (listening effort) ölçülebilir biçimde yüksektir ve bu yorgunluk
   bilişsel kaynakları tüketir. English B HL ve French B'nin dinleme bileşenleri bu yüzden
   diğer becerilerden orantısız maliyetli — ayrı izlenmeyi hak ediyor. */
const DINLEME_TUR = {
  ders:   { ad: "Sınıf dersi", yuk: 3, ip: "Uzak mikrofonu öğretmene yaklaştır; arka gürültü en büyük düşman." },
  video:  { ard: 0, ad: "Video / ders kaydı", yuk: 2, ip: "Altyazı varsa aç — çift kodlama dinleme çabasını düşürür." },
  sinav:  { ad: "Dinleme sınavı pratiği", yuk: 4, ip: "Gerçek koşul: tek dinleme, not alarak. En yüksek yük burada." },
  sohbet: { ad: "Konuşma pratiği", yuk: 3, ip: "Sessiz ortam seç; iki kişiyi aynı anda dinlemek yükü ikiye katlar." },
  muzik:  { ad: "Pasif dinleme", yuk: 1, ip: "Düşük yük ama düşük getiri. Aktif dinlemenin yerini tutmaz." },
};
function dinlemeEkle(d, k, bugun) {
  return { ...d, dinlemeler: [...(d.dinlemeler || []), {
    id: "dl" + Date.now().toString(36), tarih: bugun, tur: k.tur, dakika: Number(k.dakika) || 0,
    ders: k.ders || "", mikrofon: !!k.mikrofon, zorluk: Number(k.zorluk) || 3, notu: k.notu || "" }].slice(-200) };
}
function dinlemeYuku(d, bugun, gun = 7) {
  const l = (d.dinlemeler || []).filter((x) => gunFark(bugun, x.tarih) < gun);
  let yuk = 0, dk = 0, mikrofonlu = 0;
  for (const x of l) { const T2 = DINLEME_TUR[x.tur] || DINLEME_TUR.video;
    yuk += (x.dakika / 60) * T2.yuk * (x.mikrofon ? 0.78 : 1); dk += x.dakika;
    if (x.mikrofon) mikrofonlu += x.dakika; }
  const bugunYuk = (d.dinlemeler || []).filter((x) => x.tarih === bugun)
    .reduce((a, x) => a + (x.dakika / 60) * (DINLEME_TUR[x.tur] || DINLEME_TUR.video).yuk * (x.mikrofon ? 0.78 : 1), 0);
  return { yuk: Math.round(yuk * 10) / 10, dk, mikrofonlu, bugunYuk: Math.round(bugunYuk * 10) / 10,
    mikrofonOran: dk ? mikrofonlu / dk : null, adet: l.length,
    kod: bugunYuk >= 6 ? "asiri" : bugunYuk >= 3.5 ? "yuksek" : bugunYuk >= 1.5 ? "orta" : "hafif" };
}
const DINLEME_AD = { asiri: ["Aşırı yük", "kirmizi", "Bugün dinleme çabası çok yüksek. Kalan çalışmayı metin temelli yap — okuma, yazma, soru çözme."],
  yuksek: ["Yüksek", "amber", "Dinleme yükü belirgin. Araya sessiz bir blok koymak dinleme performansını korur."],
  orta: ["Orta", "teal", "Dengeli. Bir dinleme sınavı pratiği daha kaldırabilirsin."],
  hafif: ["Hafif", "mavi", "Dinleme bileşenleri en çok ihmal edilen ve en çok pratik isteyen kısım."] };

