/* IB Kasım 2027 oturumuyla DP biter; YKS bir sonraki Haziran'dadır — 2028. */
const SINAV_TARIH = { ib: "2027-11-01", yks: "2028-06-17" };
function teslimKur(d, bugun) {
  const bas = bugun;
  /* hiçbir teslim IB sınav oturumundan sonraya düşmemeli — en geç 30 gün önce biter */
  const tavan = addDays(SINAV_TARIH.ib, -30);
  return IB_BILESEN.map((b) => {
    let son = addDays(bas, Math.round(b.ay * 30.4));
    if (gunFark(son, tavan) > 0) son = tavan;
    const n = b.parca.length;
    const sure = Math.max(30, gunFark(son, bas));
    return { id: b.id, ad: b.ad, ders: b.ders, tip: b.tip, tarih: son, baslangic: bas,
      parcalar: b.parca.map((p2, i) => ({ ad: p2, tarih: addDays(bas, Math.round(sure * ((i + 1) / n))), bitti: false })) };
  });
}
function teslimOzet(d, bugun) {
  const t = d.teslimler || [];
  const hepsi = t.map((x) => {
    const parc = x.parcalar || [];
    const bitti = parc.filter((p2) => p2.bitti).length;
    const siradaki = parc.find((p2) => !p2.bitti);
    const kalan = gunFark(x.tarih, bugun);
    const oran = parc.length ? bitti / parc.length : 0;
    /* beklenen ilerleme: zamanın ne kadarı geçti */
    const toplamGun = Math.max(1, gunFark(x.tarih, x.baslangic || addDays(bugun, -1)));
    const gecikme = siradaki ? gunFark(bugun, siradaki.tarih) : 0;
    return { ...x, bitti, toplam: parc.length, oran, siradaki, kalan, gecikme,
      kod: oran >= 1 ? "bitti" : gecikme > 14 ? "kritik" : gecikme > 0 ? "gecikmis"
        : kalan <= 30 ? "yakin" : "akiyor" };
  });
  const oncelik = { kritik: 0, gecikmis: 1, yakin: 2, akiyor: 3, bitti: 4 };
  return hepsi.sort((a, b) => (oncelik[a.kod] - oncelik[b.kod]) || (a.kalan - b.kalan));
}
const TESLIM_AD = { bitti: ["Tamamlandı", "yesil"], kritik: ["Kritik gecikme", "kirmizi"],
  gecikmis: ["Gecikmiş", "turuncu"], yakin: ["Yaklaşıyor", "amber"], akiyor: ["Planda", "teal"] };

/* ── GERİ SAYIM ve GELECEKTEKİ BENLİK ──
   Ersner-Hershfield: gelecekteki benliği düşünmek, bir BAŞKASINI düşünmeye benzer nöral
   aktivasyon üretir. O yüzden onun uğruna bugün fedakârlık yapmak zordur. Çare: onu
   somutlaştırmak — soyut bir "gelecek" değil, sayılabilir bir mesafe ve bir tablo. */
function geriSayim(d, bugun) {
  const ib = gunFark(SINAV_TARIH.ib, bugun), yks = gunFark(SINAV_TARIH.yks, bugun);
  const hafta = (g) => Math.max(0, Math.round(g / 7));
  return { ib, yks, ibHafta: hafta(ib), yksHafta: hafta(yks),
    yakin: yks <= ib ? { ad: "YKS", gun: yks } : { ad: "IB Kasım oturumu", gun: ib } };
}
function gelecekProjeksiyon(d, bugun) {
  try {
    const gs = geriSayim(d, bugun);
    const c = haftalikCikti(d, bugun), g = gerceklikKat(d, bugun);
    const { onbir } = ilkOnbir({ ...d, oyuncular: onizleme(d, bugun) }, "lig");
    const simdi = Math.round(takimGucu(onbir).takimOVR);
    /* mevcut haftalık tempo sürerse: kaba ama veriye dayalı bir izdüşüm */
    const haftalikKazanc = clamp((c.dk / 900) * (g.bekliyor ? 0.55 : clamp(g.kat, 0.5, 1.2)) * 0.9, 0, 2.2);
    const hafta = Math.max(0, gs.yksHafta);
    const hedef = clamp(Math.round(simdi + haftalikKazanc * hafta * 0.55), simdi, 99);
    return { simdi, hedef, haftalikKazanc: Math.round(haftalikKazanc * 100) / 100, hafta,
      toplamSaat: Math.round((c.dk / 60) * hafta) };
  } catch (e) { return null; }
}

/* ── HAFTA KAPANIŞI ──
   Öz-düzenlemenin somut hâli. Rapor: plan bir sözleşme değil hipotezdir; kritik olan
   plan bozulduğunda ne yapıldığıdır. Haftalık tek bir değişiklik taahhüdü, on maddelik
   niyet listesinden daha etkilidir. */
function haftaNo(d, bugun) { return Math.floor(gunFark(bugun, d.sezon.baslangic) / 7); }
function haftaVerisi(d, bugun) {
  let dk = 0, gun = 0, soru = 0, dogru = 0;
  for (let i = 0; i < 7; i++) { const se = d.antrenman[addDays(bugun, -i)] || [];
    if (se.length) gun++;
    for (const x of se) { dk += Number(x.dakika) || 0; soru += Number(x.soru) || 0;
      dogru += x.dogru != null ? Number(x.dogru) : (Number(x.soru) || 0) * (Number(x.dogruluk) || 0) / 100; } }
  const to = toplaOynama(d, bugun);
  const g = gerceklikKat(d, bugun);
  return { dk, gun, soru, isabet: soru ? Math.round((dogru / soru) * 100) : null,
    aktifOran: to.oran, donusum: g.bekliyor ? null : Number(g.kat.toFixed(2)) };
}
const KAPANIS_SORU = [
  { k: "isleyen", s: "Bu hafta ne işledi?", ip: "Somut ol: hangi yöntem, hangi saat, hangi ders" },
  { k: "islemeyen", s: "Ne işlemedi?", ip: "Suçlama değil teşhis — neyi yanlış kurmuşum" },
  { k: "tekDegisiklik", s: "Gelecek hafta TEK bir değişiklik", ip: "Bir tane. On madde hiçbir madde demektir" },
];

