/* Günün görevleri — tarihe göre deterministik, her gün yenilenir */
function gunlukGorevler(d, bugun) {
  const rng = rngFor("gorev", bugun, d.kulup.ad, d.sezon.no);
  const havuz = [...GOREV_HAVUZ];
  /* karıştır */
  for (let i = havuz.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = havuz[i]; havuz[i] = havuz[j]; havuz[j] = t; }
  const adet = 3 + (rng() > 0.45 ? 1 : 0);
  return havuz.slice(0, adet).map((g, i) => {
    const v = g.hedef(rngFor("gorevH", bugun, g.id, i));
    const o = g.olc(d, bugun, v) || { simdi: 0, hedef: 1, birim: "" };
    const tamam = o.simdi >= o.hedef;
    return { ...g, v, ...o, tamam, Z: GOREV_ZORLUK[g.zor], anahtar: g.id + "-" + bugun };
  });
}
const gorevPuani = (gs) => gs.filter((g) => g.tamam).reduce((a, g) => a + g.Z.puan, 0);
const gorevHepsi = (gs) => gs.length > 0 && gs.every((g) => g.tamam);

