const ESYA_ID = Object.keys(ESYA);
/* sandık aç — nadirlik ağırlıklı çekiliş */
function sandikAc(d, bugun, kalite) {
  const rng = rngFor("sandik", bugun, ((d.envanter || {}).gecmis || []).length, kalite);
  const bonus = { normal: 0, iyi: 14, muhtesem: 34 }[kalite] || 0;
  const ag = ESYA_ID.map((id) => {
    const n = NADIRLIK[ESYA[id].nadir];
    return Math.max(1, n.agirlik + (n.agirlik < 30 ? bonus : -bonus * 0.35));
  });
  const top = ag.reduce((a, x) => a + x, 0);
  let r = rng() * top;
  for (let i = 0; i < ag.length; i++) { r -= ag[i]; if (r <= 0) return ESYA_ID[i]; }
  return ESYA_ID[0];
}
function esyaEkle(d, id, adet = 1) {
  const e = { esyalar: {}, gecmis: [], acilanGun: [], ...(d.envanter || {}) };
  return { ...d, envanter: { ...e, esyalar: { ...e.esyalar, [id]: (e.esyalar[id] || 0) + adet },
    gecmis: [...(e.gecmis || []), { id, tarih: "kazanildi" }].slice(-60) } };
}
function esyaKullan(d, id, bugun) {
  const e = { esyalar: {}, gecmis: [], acilanGun: [], ...(d.envanter || {}) };
  if (!(e.esyalar[id] > 0) || !ESYA[id]) return d;
  const sonra = ESYA[id].uygula(d, bugun) || d;
  const e2 = { esyalar: {}, gecmis: [], acilanGun: [], ...(sonra.envanter || e) };
  return { ...sonra, envanter: { ...e2, esyalar: { ...e2.esyalar, [id]: (e2.esyalar[id] || 1) - 1 } } };
}

/* ═══════════ MOTİVASYON MOTORU ═══════════
   Kaynak: "Video Oyunları ve İnsan Zihni" raporu. Yalnızca GÜÇLÜ kanıtlı mekanizmalar alındı.
   · Akış koridoru — Csikszentmihalyi: zorluk ile beceri dengede olduğunda daldırma doğar
   · Ödül tahmin hatası — Schultz (★★★★★): beyin hazzı değil, beklenti-gerçek farkını öğrenir
   · Üç temel ihtiyaç — Ryan/Rigby/Przybylski (★★★★): yeterlilik, özerklik, ilişkili olma
   · İşlevsellik bekçisi — ICD-11: ölçüt saat değil, hayatın diğer alanlarının bozulmasıdır
   Bilinçli olarak EKLENMEYENLER (rapor bunları risk olarak işaretliyor):
   günlük giriş ödülü, sonu olmayan ilerleme, kaçırma korkusu, rastgele ödül sandığı. */

/* ── AKIŞ KORİDORU ──
   Çok kolay → can sıkıntısı. Çok zor → kaygı. İkisinin arası → akış. */
const AKIS_DURUM = {
  sikinti:  { ad: "Can sıkıntısı", renk: "mavi",    ac: "Görev becerinin altında — zorluğu yükselt" },
  akis:     { ad: "Akış",          renk: "yesil",   ac: "Zorluk ve beceri dengede. İdeal bölge." },
  gerilim:  { ad: "Gerilim",       renk: "amber",   ac: "Sınırdasın — bu iyi ama uzun tutma" },
  kaygi:    { ad: "Kaygı",         renk: "kirmizi", ac: "Görev becerinin çok üstünde — parçala ya da kolaylaştır" },
  veriYok:  { ad: "Veri yok",      renk: "lo",      ac: "Birkaç ölçümlü seans sonrası hesaplanır" },
};
function akisDurumu(d, p2, bugun) {
  try {
    const gc = (Array.isArray(p2.gecmis) ? p2.gecmis : []).filter((x) => x.soru >= 5).slice(-6);
    if (gc.length < 2) return { kod: "veriYok", isabet: null, oneriZorluk: 2, fark: 0 };
    const isabet = gc.reduce((a, x) => a + (x.dogru / Math.max(1, x.soru)), 0) / gc.length;
    /* hedef bant %70–85: bu aralıkta öğrenme en verimli, üstü kolay altı bunaltıcı */
    const kod = isabet >= 0.93 ? "sikinti" : isabet >= 0.85 ? "gerilim" : isabet >= 0.68 ? "akis"
      : isabet >= 0.5 ? "gerilim" : "kaygi";
    const ortZor = gc.reduce((a, x) => a + (x.zorluk || 2), 0) / gc.length;
    const oneriZorluk = clamp(Math.round(isabet >= 0.9 ? ortZor + 1 : isabet < 0.55 ? ortZor - 1 : ortZor), 1, 4);
    return { kod, isabet, oneriZorluk, fark: Math.round((isabet - 0.775) * 100) };
  } catch (e) { return { kod: "veriYok", isabet: null, oneriZorluk: 2, fark: 0 }; }
}

/* ── ÖDÜL TAHMİN HATASI ──
   Dopamin hazzı değil "beklenenden iyi/kötü" sinyalini kodlar. Bu paneli görünür kılmak,
   ilerlemeyi beynin gerçekten öğrendiği biçimde okunur hale getirir. */
function tahminHatasi(d, p2, seans) {
  try {
    const gc = (Array.isArray(p2.gecmis) ? p2.gecmis : []).filter((x) => x.soru >= 5).slice(-5);
    if (!gc.length || !seans || !seans.soru) return null;
    const beklenen = gc.reduce((a, x) => a + (x.dogru / Math.max(1, x.soru)), 0) / gc.length;
    const gercek = (seans.dogru != null ? seans.dogru : seans.dogruluk) / (seans.soru ? 100 : 1);
    const olan = seans.dogru != null ? seans.dogru / Math.max(1, seans.soru) : (seans.dogruluk || 0) / 100;
    const hata = olan - beklenen;
    return { beklenen, olan, hata,
      yon: hata > 0.08 ? "olumlu" : hata < -0.08 ? "olumsuz" : "beklendik",
      metin: hata > 0.08 ? "Beklenenin üstünde — öğrenme sinyali güçlü"
        : hata < -0.08 ? "Beklenenin altında — konu henüz oturmamış"
        : "Tam beklendiği gibi — bu konu artık istikrarlı" };
  } catch (e) { return null; }
}

/* ── ÜÇ TEMEL İHTİYAÇ (Kendi Kaderini Tayin Kuramı) ──
   Rapordaki kritik uyarı: sanal doyum gerçektir, ama gerçek hayattaki açığı sürekli
   ikame ediyorsa kalıcı olmaz. Bu yüzden panel HEM uygulamayı HEM gerçek hayatı sorar. */
function ihtiyacDoyumu(d, bugun) {
  try {
    const { onbir } = ilkOnbir({ ...d, oyuncular: onizleme(d, bugun) }, "lig");
    const c = haftalikCikti(d, bugun), g = gerceklikKat(d, bugun);
    const bak = bakimListesi(d, bugun);
    const guncel = bak.filter((x) => x.kod === "taze" || x.kod === "yaklasan").length;
    /* YETERLİLİK: ölçülmüş gelişim + bakım güncelliği + dönüşüm */
    const yeterlilik = clamp(Math.round(
      (g.bekliyor ? 25 : clamp(g.kat, 0.5, 1.2) * 45) +
      (guncel / Math.max(1, bak.length)) * 30 +
      clamp(c.dogruluk * 25, 0, 25)), 0, 100);
    /* ÖZERKLİK: kendi seçtiğin roller, program, taktik — dayatma değil tercih */
    const rolSecim = onbir.filter((p2) => p2.rolBaslangic).length / Math.max(1, onbir.length);
    const ozerklik = clamp(Math.round(rolSecim * 40 + (d.haftalikPlan ? 30 : 12)
      + ((d.taktikler || []).length > 1 ? 20 : 8) + ((d.sosyal || {}).gonderiler || []).length * 2), 0, 100);
    /* İLİŞKİLİ OLMA: bu uygulama tek başına dolduramaz — düşük çıkması normaldir */
    const iliski = clamp(Math.round(((d.ekip || []).length * 8)
      + ((d.sosyal || {}).gonderiler || []).length * 4 + 10), 0, 100);
    return { yeterlilik, ozerklik, iliski };
  } catch (e) { return { yeterlilik: 0, ozerklik: 0, iliski: 0 }; }
}

/* ── İŞLEVSELLİK BEKÇİSİ ──
   ICD-11'in gerçek ölçütü: süre değil, hayatın diğer alanlarının bozulması.
   Ayrıca bu uygulamaya özgü risk: uygulamayla oynamak, ders çalışmanın yerine geçebilir. */
function islevsellikKontrol(d, bugun) {
  const uyari = [];
  try {
    const c = haftalikCikti(d, bugun);
    const seri = seriGun(d, bugun);
    /* 1) uygulama, çalışmanın yerine mi geçiyor? */
    const macSayisi = (d.maclar || []).filter((m) => gunFark(bugun, m.tarih) <= 7).length;
    const hazirlik = ((d.hazirlik || {}).gecmis || []).filter((m) => gunFark(bugun, m.tarih) <= 7).length;
    if (c.dk < 180 && (macSayisi + hazirlik) >= 4)
      uyari.push({ tur: "ikame", ad: "Uygulama çalışmanın yerine geçiyor",
        ac: `Bu hafta ${c.dk} dakika çalıştın ama ${macSayisi + hazirlik} maç oynadın. Uygulama aracı, hedef değil.` });
    /* 2) geç saat örüntüsü — uyku işlevselliğin ilk kaybedilen alanı */
    let gecSeans = 0;
    for (let i = 0; i < 7; i++) for (const x of (d.antrenman[addDays(bugun, -i)] || []))
      if (gecSaatMi(x.saat, ritimAl(d))) gecSeans++;
    if (gecSeans >= 4) uyari.push({ tur: "uyku", ad: "Uyku saatine taşan seanslar",
      ac: `Son 7 günde ${gecSeans} seans uyku saatlerine taştı (${ritimAl(d).yatis}–${ritimAl(d).kalkis}). Uyku, performansın en ucuz kaynağı.` });
    /* 3) aşırı tek gün yüklenme — sağlıklı bir örüntü değil */
    const bugunDk = (d.antrenman[bugun] || []).reduce((a, x) => a + x.dakika, 0);
    if (bugunDk > 420) uyari.push({ tur: "asiri", ad: "Bugün çok uzun bir gün",
      ac: `${bugunDk} dakika. Doygunluk eğrisi gereği son saatlerin verimi ilk saatlerin çok altında.` });
    /* 4) sıfır ölçüm — sanal ilerleme gerçek ilerlemeyi ikame ediyor olabilir */
    const g = gerceklikKat(d, bugun);
    if (g.bekliyor && c.dk > 600) uyari.push({ tur: "olcum", ad: "Ölçümsüz ilerleme",
      ac: "Çok çalışıyorsun ama hiç resmî ölçüm yok. Rakamların sahadaki karşılığı bilinmiyor." });
  } catch (e) {}
  return uyari;
}

/* ═══════════ BAKIM ANTRENMANI · aralıklı tekrar ═══════════
   Bu uygulamanın en büyük eksiğiydi: ne zaman TEKRAR edileceğini söylemiyordu.
   Futbol karşılığı: bir oyuncu maç keskinliğini kaybetmesin diye düzenli bakım antrenmanı görür.
   Gerçek karşılığı: unutma eğrisine karşı aralıklı tekrar. Aralıklar isabete göre uzar ya da kısalır. */
const TEKRAR_ARALIK = [1, 3, 7, 16, 35, 70, 120];
const BAKIM_DURUM = {
  taze:    { ad: "Taze", renk: "teal",    ac: "Yakında tekrar gerekmiyor" },
  yaklasan:{ ad: "Yaklaşıyor", renk: "mavi", ac: "Birkaç gün içinde bakım" },
  bugun:   { ad: "Bugün", renk: "amber",  ac: "Bugün bakım günü" },
  gecikmis:{ ad: "Gecikmiş", renk: "turuncu", ac: "Bakım tarihi geçti, keskinlik düşüyor" },
  kritik:  { ad: "Kritik", renk: "kirmizi", ac: "Uzun süredir dokunulmadı, ciddi kayıp var" },
  yeni:    { ad: "Başlanmadı", renk: "lo", ac: "Henüz nitelikli bir seans yok" },
};
/* bir dersin bakım durumu */
function bakimDurumu(d, p, bugun) {
  const b = (p && p.bakim) || {};
  if (!b.sonTekrar) return { kod: "yeni", seviye: 0, gecikme: 0, sonraki: null, aralik: TEKRAR_ARALIK[0], keskinlik: 100 };
  const sv = clamp(b.seviye || 0, 0, TEKRAR_ARALIK.length - 1);
  const aralik = TEKRAR_ARALIK[sv];
  const sonraki = addDays(b.sonTekrar, aralik);
  const gecikme = gunFark(bugun, sonraki);                    /* >0 = gecikti */
  const kod = gecikme >= aralik ? "kritik" : gecikme > 0 ? "gecikmis" : gecikme === 0 ? "bugun"
    : gecikme >= -3 ? "yaklasan" : "taze";
  /* keskinlik: gecikme büyüdükçe düşer, tekrar edilince geri gelir */
  const keskinlik = clamp(100 - Math.max(0, gecikme) * (100 / Math.max(4, aralik * 1.6)), 45, 100);
  return { kod, seviye: sv, gecikme, sonraki, aralik, keskinlik };
}
/* keskinlik OVR'a küçük ama gerçek bir etki yapar — tekrar edilmeyen bilgi solar */
const keskinlikKat = (d, p, bugun) => {
  try { return 0.94 + (bakimDurumu(d, p, bugun).keskinlik / 100) * 0.06; } catch (e) { return 1; }
};
/* nitelikli bir seans bakım takvimini ilerletir */
function bakimGuncelle(p, seans, tarih) {
  const soru = Number(seans.soru) || 0, dog = Number(seans.dogruluk) || 0;
  const dk = Number(seans.dakika) || 0;
  if (dk < 15) return p.bakim || {};                            /* çok kısa seans sayılmaz */
  const b = { ...(p.bakim || { seviye: 0 }) };
  const sv = clamp(b.seviye || 0, 0, TEKRAR_ARALIK.length - 1);
  if (soru >= 5 && dog >= 80) b.seviye = clamp(sv + 1, 0, TEKRAR_ARALIK.length - 1);   /* iyi → aralık uzar */
  else if (soru >= 5 && dog >= 55) b.seviye = sv;                                       /* orta → sabit */
  else if (soru >= 5) b.seviye = clamp(sv - 1, 0, TEKRAR_ARALIK.length - 1);            /* zayıf → kısalır */
  else b.seviye = clamp(sv, 0, TEKRAR_ARALIK.length - 1);                               /* ölçümsüz → sabit */
  b.sonTekrar = tarih;
  b.gecmisSayi = (b.gecmisSayi || 0) + 1;
  return b;
}
/* bugün bakım bekleyenler — aciliyete göre sıralı */
function bakimListesi(d, bugun) {
  const oncelik = { kritik: 0, gecikmis: 1, bugun: 2, yeni: 3, yaklasan: 4, taze: 5 };
  return d.oyuncular.filter((p) => p.kol === "lig")
    .map((p) => ({ p, ...bakimDurumu(d, p, bugun) }))
    .sort((a, b) => (oncelik[a.kod] - oncelik[b.kod]) || (b.gecikme - a.gecikme));
}

/* ═══════════ ROTASYON HAKKI · seri koruma ═══════════
   Tek bir kötü gün 40 günlük seriyi silmemeli. Hedefi aşan haftalar rotasyon hakkı kazandırır;
   bir hak harcayarak boş bir günü "planlı dinlenme" sayarsın ve seri korunur. */
const ROTASYON_AZAMI = 3;
function rotasyonKazanci(d, bugun) {
  const r = d.rotasyon || { hak: 0, kullanilan: [], kazanilan: [] };
  const hafta = Math.floor(gunFark(bugun, d.sezon.baslangic) / 7);
  if ((r.kazanilan || []).includes(hafta)) return null;
  let dk = 0, gun = 0;
  for (let i = 0; i < 7; i++) { const se = d.antrenman[addDays(bugun, -i)] || [];
    if (se.length) { gun++; dk += se.reduce((a, x) => a + x.dakika, 0); } }
  if (gun >= 6 && dk >= HAFTALIK_DK * 0.9) return { hafta, dk, gun };
  return null;
}
const rotasyonKorumali = (d, tarih) => ((d.rotasyon || {}).kullanilan || []).includes(tarih);
/* seri hesabı korumalı günleri atlar */
function seriGunKorumali(d, tarih) {
  let n = 0;
  for (let i = 0; i < 400; i++) {
    const t = addDays(tarih, -i);
    if ((d.antrenman[t] || []).length) { n++; continue; }
    if (rotasyonKorumali(d, t)) continue;                        /* korumalı gün seriyi kırmaz */
    if (i > 0) break;
  }
  return n;
}

/* ═══════════ SIRADAKİ HAMLE · tek karar ═══════════
   Uygulamanın 60 ekranı var ama günlük soru tek: "şimdi ne yapmalıyım?"
   Bu fonksiyon veriyi okuyup TEK bir cevap üretir. Ağ gerektirmez, anında çalışır. */
function siradakiHamle(d, bugun, kilitli) {
  try {
    const { onbir } = ilkOnbir({ ...d, oyuncular: onizleme(d, bugun) }, "lig");
    const zayif = enZayifHalka(onbir);
    const bak = bakimListesi(d, bugun);
    const bugunSe = d.antrenman[bugun] || [];
    const bugunDk = bugunSe.reduce((a, x) => a + x.dakika, 0);
    const seri = seriGunKorumali(d, bugun);
    const g = gerceklikKat(d, bugun);
    const yorgun = onbir.filter((p) => p.kondisyon < 35).length;
    const H = (tur, baslik, sebep, eylem, hedef, renk, pid) => ({ tur, baslik, sebep, eylem, hedef, renk, pid });

    /* işlevsellik uyarısı her şeyin önünde gelir — ICD-11 ölçütü budur */
    /* uyku borcu birikmişse dikkat ve öğrenme zaten sınırlı — önce bu söylenir */
    const uyk = uykuOzet(d, bugun);
    if (uyk.n >= 4 && uyk.borc >= 10) return H("uyku", `Uyku borcu ${uyk.borc} saat`,
      `Son ${uyk.n} gecede ortalama ${uyk.ort} saat uyudun. Uyku, hafıza konsolidasyonunun gerçekleştiği zamandır — borç biriktikçe aynı çalışma daha az yapışır.`,
      "Uykuya bak", ["uyku"], "turuncu");
    /* aşırı dinleme yükü — kalan çalışmayı metin temelli yapmak gerekiyor */
    const dyk = dinlemeYuku(d, bugun);
    if (dyk.kod === "asiri") return H("dinleme", "Dinleme yükü aşırı",
      `Bugün ${dyk.bugunYuk} birim dinleme çabası birikti. Dinleme çabası bilişsel kaynak tüketir — kalan çalışmayı metin temelli yap: okuma, yazma, soru çözme.`,
      "Dinleme yüküne bak", ["dinleme"], "kirmizi");
    /* konu haritası kuruluysa: oturmuş konu oranı düşükse kapalı kitap öner */
    if ((d.konular || []).length) {
      const ko = konuOzet(d);
      const islenmis = (d.konular || []).filter((x) => x.kademe === "islendi");
      if (islenmis.length >= 3 && ko.fetih < 0.25) {
        const hedefK = islenmis[Math.floor(rngFor("konuOner", bugun)() * islenmis.length)];
        return H("anlatma", `${hedefK.ad} oturmadı`,
          `${islenmis.length} konu "işlendi" ama sadece ${ko.say.oturdu} tanesi oturdu. Tanımak bilmek değil — kaynağı kapat, boş kâğıda anlat. Bu, literatürdeki en güçlü kanıtlı teknik.`,
          "Kapalı kitap başlat", ["anlatma"], "teal", hedefK.pid);
      }
    }
    /* gecikmiş yüksek öncelikli görev ya da kritik teslim, çalışma önerisinden önce gelir */
    const gz = gorevOzet(d, bugun);
    const acilGorev = gz.gecmis.find((x) => x.oncelik === "yuksek") || (gz.gecmis.length >= 3 ? gz.gecmis[0] : null);
    if (acilGorev) return H("gorev", acilGorev.metin,
      `${gunFark(bugun, acilGorev.tarih)} gün gecikti · ${acilGorev.liste} listesi. Gecikmiş görev listesi büyüdükçe her biri daha itici hâle gelir.`,
      "Görevleri aç", ["ajanda"], "kirmizi");
    const kritikT = teslimOzet(d, bugun).find((x) => x.kod === "kritik");
    if (kritikT && kritikT.siradaki) return H("teslim", `${kritikT.ad} gecikti`,
      `Sıradaki parça "${kritikT.siradaki.ad}" ${kritikT.gecikme} gün gecikmiş. Bileşenin bütününe bakmak ertelemeyi besler — tek parçaya odaklan.`,
      "Teslimleri aç", ["teslim"], "kirmizi");
    /* kayma varsa asgari oturum her şeyin önünde — AVE döngüsünü kırmak birinci öncelik */
    const ky = kaymaDurumu(d, bugun);
    if (ky.kod === "risk" || ky.kod === "cokus") return H("kayma", `${ky.bosGun} gün boş geçti`,
      "Bu bir veri, bir yargı değil. Şimdi 10 saate kalkışmak çöküşü derinleştirir — sisteme dokunmak yeter: 15 dakika, 5 soru.",
      "Asgari oturumu aç", ["sistem"], "turuncu");
    /* zemin koşulları kritikse en yüksek kaldıraç orada */
    const zm2 = surtunmeSkoru(d);
    if (zm2.kod === "kritik") { const en = [...zm2.eksik].sort((a, b) => b.puan - a.puan)[0];
      return H("zemin", "Zemin bakımsız", `${en.ad} işaretli değil. Hedefe ulaşmayı belirleyen şey ayartıya direnmek değil, onunla daha az karşılaşmak — tek madde bir hafta iradeden daha etkili.`,
        "Zemini kur", ["sistem"], "kirmizi"); }
    /* aktif oran çok düşükse saat eklemek işe yaramaz, yöntem değişmeli */
    const to2 = toplaOynama(d, bugun);
    if (to2.toplam > 240 && to2.oran != null && to2.oran < 0.32) return H("oynama", "Pasif çalışma baskın",
      `Haftalık ${to2.toplam} dakikanın yalnızca %${Math.round(to2.oran * 100)}'i aktif. Bu saat ekleyerek düzelmez — kaynağı kapat, boş kâğıda anlat, sonra soru çöz.`,
      "Topla oynamaya bak", ["sistem"], "turuncu");
    const isl = islevsellikKontrol(d, bugun);
    if (isl.length) return H("islev", isl[0].ad, isl[0].ac, "Motivasyon ekranını aç", ["motivasyon"], "turuncu");
    if (d.devreBekleyen) return H("mac", "Maçın seni bekliyor", "Sahada oynanacak bir karşılaşma var. Emeğinin karşılığını izle.", "Maçı izle", ["mac"], "mor");
    const fx = (d.sezon.fikstur || []).find((f) => !f.oynandi && !f.ertelendi);
    if (fx && fx.tarih === bugun && kilitli) return H("mac", `${fx.rakip} maçı bugün`, "Kadro kilitlendi. Maç saati geldiğinde oynanacak.", "Maç Merkezi", ["mac"], "mor");

    const kritikler = bak.filter((x) => x.kod === "kritik");
    const kritik = kritikler.length ? kritikler[Math.floor(rngFor("hamle", bugun)() * kritikler.length)] : null;
    if (kritik) return H("bakim", `${kritik.p.ad} bakım bekliyor`,
      `Son nitelikli tekrardan bu yana ${kritik.gecikme + kritik.aralik} gün geçti. Keskinlik %${Math.round(kritik.keskinlik)}'e düştü — bilgi soluyor.`,
      "Bakım seansı ekle", ["bugun"], "kirmizi", kritik.p.id);

    if (bugunDk === 0 && yorgun >= 4) return H("dinlenme", "Bugün dinlenme günü",
      `${yorgun} ders yorgun. Kondisyon düşükken yapılan antrenmanın verimi ciddi düşer — dinlenme de antrenmandır.`,
      "Programı gözden geçir", ["bugun"], "teal");

    const gecikler = bak.filter((x) => x.kod === "gecikmis" || x.kod === "bugun");
    const gecik = gecikler.length ? gecikler[Math.floor(rngFor("hamle2", bugun)() * gecikler.length)] : null;
    if (gecik) return H("bakim", `${gecik.p.ad} tekrar günü`,
      gecik.gecikme > 0 ? `${gecik.gecikme} gün gecikti. Aralık ${gecik.aralik} gündü.` : `Bugün ${gecik.aralik} günlük aralığın sonu. Şimdi tekrar edersen aralık uzar.`,
      "Bu derse seans ekle", ["bugun"], "amber", gecik.p.id);

    if (zayif && matchOVR(zayif.oyuncu) < 45) return H("zayif", `${zayif.oyuncu.ad} takımı aşağı çekiyor`,
      `${Math.round(matchOVR(zayif.oyuncu))} OVR ile takım gücünü ${zayif.kayip} puan düşürüyor. Harmonik ortalama en zayıf halkayı affetmez.`,
      "Zayıf halkaya çalış", ["bugun"], "turuncu", zayif.oyuncu.id);

    if (g.bekliyor) return H("olcum", "Ölçüm girmen gerekiyor",
      "Reytinglerin doğrulanmadı. En az iki resmî ölçüm girmeden bu rakamların sahada karşılığı olduğu bilinemez.",
      "Ölçüm ekle", ["kulup", "olcum"], "mavi");
    if (g.kat < 0.85) return H("olcum", "Dönüşümün düşük",
      `Antrenmanda iyisin ama sahada karşılığı yok — dönüşüm ${g.kat.toFixed(2)}. Sorun büyük ihtimalle seans türünde ya da sınav koşulunda.`,
      "Denetim raporunu al", ["kulup", "olcum"], "mavi");

    /* akış koridoru dışına düşmüş ders varsa zorluk ayarı öner */
    const disari = onbir.map((p2) => ({ p: p2, ...akisDurumu(d, p2, bugun) }))
      .filter((a) => a.kod === "kaygi" || a.kod === "sikinti");
    if (disari.length && bugunDk === 0) { const a = disari[0];
      return H("akis", `${a.p.ad} akış dışında`,
        a.kod === "kaygi"
          ? `İsabet %${Math.round(a.isabet * 100)} — görev becerinin çok üstünde. Zorluğu ${a.oneriZorluk}'e indir ya da konuyu parçala.`
          : `İsabet %${Math.round(a.isabet * 100)} — görev fazla kolay, öğrenme durdu. Zorluğu ${a.oneriZorluk}'e çıkar.`,
        "Zorluğu ayarla", ["bugun"], a.kod === "kaygi" ? "kirmizi" : "mavi", a.p.id); }
    if (bugunDk === 0) return H("baslat", seri > 0 ? `Seriyi ${seri + 1}. güne taşı` : "Bugün henüz başlamadın",
      seri >= 7 ? `${seri} günlük seri sürüyor. Bugün de bir seans yeter.` : "İlk pomodoro en zor olanı. Yirmi beş dakika.",
      "İlk seansı başlat", ["bugun"], "yesil");
    if (bugunDk < 120) return H("devam", "Devam et", `Bugün ${bugunDk} dakika. Blokları tamamlamaya az kaldı.`, "Antrenmana dön", ["bugun"], "yesil");
    return H("tamam", "Bugünkü iş bitti", `${bugunDk} dakika çalıştın${seri ? `, seri ${seri} gün` : ""}. Kadroyu gözden geçirmek için iyi bir zaman.`, "Takımı incele", ["kadro"], "limon");
  } catch (e) { return null; }
}

