/* kulübün ülkesine göre ulusal kupa ve süper kupa */
function ulusalKupalar(d) {
  const lig = LIGLER[(d.kulup && d.kulup.lig) || KADEME_LIG[d.kulup ? d.kulup.kademe : 5]] || LIGLER["tr-3"];
  const u = lig.ulke;
  const kupa = Object.entries(TURNUVALAR).filter(([, t]) => t.ulke === u && t.tip === "ulusal").map(([k]) => k);
  const sup = Object.entries(TURNUVALAR).filter(([, t]) => t.ulke === u && t.tip === "super").map(([k]) => k);
  return { kupa, sup, ulke: u };
}
/* Avrupa kupası hakkı: geçen sezon sırasına göre */
function avrupaHakki(d) {
  if (!d || !d.kulup) return null;
  const gecen = ((d.arsiv && d.arsiv.sezonlar) || []).slice(-1)[0];
  if (!gecen) return d.kulup.kademe <= 2 ? "konferans" : null;
  const s2 = gecen.sira, kad = d.kulup.kademe;
  if (kad <= 2) { if (s2 <= 2) return "sampiyonlar"; if (s2 <= 4) return "avrupa"; if (s2 <= 6) return "konferans"; return null; }
  if (kad === 3) { if (s2 <= 2) return "avrupa"; if (s2 <= 5) return "konferans"; return null; }
  return s2 === 1 ? "konferans" : null;
}
/* sezon başında turnuva takvimini kur */
function turnuvaKur(d, tarih) {
  if (!d || !d.kulup) return {};
  const uk = ulusalKupalar(d);
  const t = {};
  const ekle = (id) => { if (TURNUVALAR[id]) t[id] = { id, tur: 0, elendi: false, kazandi: false, gecmis: [] }; };
  for (const k of uk.kupa) ekle(k);                                   /* ulusal kupa(lar) */
  const av = avrupaHakki(d);
  if (av) ekle(av);
  const gecen = ((d.arsiv && d.arsiv.sezonlar) || []).slice(-1)[0];
  const gecenKupa = ((d.arsiv && d.arsiv.kupalar) || []).filter((k) => gecen && k.sezon === gecen.sezon);
  if (gecen && (gecen.sira === 1 || gecenKupa.length)) for (const sk of uk.sup) ekle(sk);
  /* Avrupa kupası kazandıysan UEFA Süper Kupa; Şampiyonlar Ligi kazandıysan Dünya Kulüpler Kupası */
  if (gecenKupa.some((k) => k.ad.includes("UEFA"))) ekle("uefaSuper");
  if (gecenKupa.some((k) => k.ad.includes("Şampiyonlar"))) ekle("dunyaKulupler");
  return t;
}
/* bir turnuvanın sıradaki maçını üret */
function turnuvaMaci(d, tk, tarih) {
  if (!d || !tk || !tk.id) return null;
  const T2 = TURNUVALAR[tk.id]; if (!T2 || tk.elendi || tk.kazandi || tk.tur >= T2.turlar.length) return null;
  const hafta = T2.haftalar[tk.tur];
  const rng = rngFor("turnuva", d.kulup.ad, d.sezon.no, tk.id, tk.tur);
  /* ── RAKİP HAVUZU · turnuvanın kapsamına göre ──
     Ulusal kupa ve süper kupa: YALNIZCA kendi ülkenden.
     Avrupa kupaları: yurt dışından (kendi ülken hariç). Dünya kupası: her yerden. */
  const taban = Math.round(takimGucu(ilkOnbir(d, "lig").onbir).takimOVR);
  const hedef = clamp(taban + T2.guc[tk.tur] + Math.round((rng() - 0.5) * 8), 42, 96);
  const kendiLig = LIGLER[kulupLigi(d)] || LIGLER["tr-3"];
  const kendiUlke = kendiLig.ulke;
  let kapsam;
  if (T2.tip === "ulusal" || T2.tip === "super") { const u = T2.ulke || kendiUlke; kapsam = ligListesi().filter((l) => l.ulke === u); }
  else if (T2.tip === "avrupa" || T2.tip === "avrupaSuper") kapsam = ligListesi().filter((l) => l.ulke !== kendiUlke && l.itibar >= 3);
  else kapsam = ligListesi();
  if (!kapsam.length) kapsam = ligListesi();
  /* güce göre daralt, boşsa kapsamın tamamını kullan */
  let havuz = kapsam.filter((l) => hedef >= l.bant[0] - 8 && hedef <= l.bant[1] + 8);
  if (!havuz.length) { const yakin = Math.min(...kapsam.map((l) => Math.abs((l.bant[0] + l.bant[1]) / 2 - hedef)));
    havuz = kapsam.filter((l) => Math.abs((l.bant[0] + l.bant[1]) / 2 - hedef) === yakin); }
  const lig = havuz[Math.floor(rng() * havuz.length)] || kapsam[0];
  const lt = ((lig && lig.takim) || []).filter((x) => x !== d.kulup.ad);
  const rakip = lt[Math.floor(rng() * Math.max(1, lt.length))] || "Rakip";
  return { no: 8000 + hashStr(tk.id) % 500 + tk.tur, tur: tk.id, turnuva: tk.id, turAd: T2.turlar[tk.tur],
    rakip, rakipOVR: hedef, evSahibi: tk.tur % 2 === 0 || T2.turlar[tk.tur] === "FİNAL" ? rng() > 0.5 : false,
    derbi: false, hafta, oynandi: false, rakipLig: lig.ad, rakipUlke: ULKELER[lig.ulke].ad };
}
/* turnuva sonucunu işle */
function turnuvaSonuc(d, tkId, mac) {
  const t = { ...(d.turnuvalar || {}) };
  const tk = t[tkId];
  if (!tk) return d;
  const T2 = TURNUVALAR[tk.id];
  const kazandik = mac.golBiz > mac.golRak || (mac.golBiz === mac.golRak && hashStr(mac.tarih + tk.id) % 2 === 0);
  const yeni = { ...tk, gecmis: [...tk.gecmis, { tur: T2.turlar[tk.tur], rakip: mac.rakip, skor: `${mac.golBiz}-${mac.golRak}`, gecti: kazandik }] };
  let mali = { ...(d.mali || {}) }, arsiv = { ...d.arsiv }, kulup = { ...d.kulup };
  if (kazandik) {
    mali.kasa = (mali.kasa || 0) + T2.odul[tk.tur];
    if (tk.tur >= (T2.turlar || []).length - 1) { yeni.kazandi = true;
      arsiv = { ...arsiv, kupalar: [...(arsiv.kupalar || []), { ad: T2.ad, sezon: d.sezon.no, kulup: d.kulup.ad }] };
      kulup = { ...kulup, prestij: clamp(kulup.prestij + 1, 1, 6), yonetimGuveni: clamp(kulup.yonetimGuveni + 14, 0, 100) };
    } else { yeni.tur = tk.tur + 1; kulup = { ...kulup, yonetimGuveni: clamp(kulup.yonetimGuveni + 3, 0, 100) }; }
  } else { yeni.elendi = true; kulup = { ...kulup, yonetimGuveni: clamp(kulup.yonetimGuveni - (tk.tur >= 3 ? 2 : 5), 0, 100) }; }
  t[tkId] = yeni;
  return { ...d, turnuvalar: t, mali, arsiv, kulup };
}
/* aktif turnuva maçları — fikstüre eklenir */
function turnuvaFikstur(d, tarih) {
  const out = [];
  if (!d || !d.turnuvalar) return out;
  for (const k of Object.keys(d.turnuvalar || {})) {
    const m = turnuvaMaci(d, d.turnuvalar[k], tarih);
    if (m) out.push(m);
  }
  return out;
}

