function momentumUret(rng, gucFark, olaylar) {
  const m = []; let v = clamp(gucFark * 2.5, -40, 40);
  for (let dk = 5; dk <= 90; dk += 5) {
    v += (rng() - 0.5) * 26 + gucFark * 0.5;
    for (const o of olaylar) if (o.dk > dk - 5 && o.dk <= dk) v += o.tip === "gol" ? (o.biz ? 32 : -32) : o.tip === "kirmizi" ? -22 : -6;
    v = clamp(v * 0.88, -100, 100); m.push({ dk, v: Math.round(v) });
  }
  return m;
}

/* ═══════════ B1 · GERÇEKLİK ÇAPASI ═══════════ */
function beklenenPuan(o, ovr) { return Math.max(1, (o.maxPuan || 100) * clamp((ovr - 35) / 60, 0.05, 1)); }
function donusumOran(d, pid, tarih) {
  const p = d.oyuncular.find((x) => x.id === pid); if (!p) return null;
  const olc = (d.olcumler || []).filter((o) => o.pid === pid && gunFark(tarih, o.tarih) <= 90 && gunFark(tarih, o.tarih) >= 0);
  if (!olc.length) return null;
  const ovr = matchOVR(p);
  const bek = olc.reduce((a, o) => a + beklenenPuan(o, ovr), 0);
  const ger = olc.reduce((a, o) => a + (Number(o.puan) || 0), 0);
  return bek > 0 ? ger / bek : null;
}
const DONUSUM_DIL = (r) => r > 1.15 ? { t: "Az şutla çok gol. Verimli forvet.", c: "iyi" } : r >= 0.85 ? { t: "Beklenen performans.", c: "notr" } : r >= 0.6 ? { t: "Çok koşuyor, gol atamıyor. Rol veya seans türü değişmeli.", c: "uyari" } : { t: "Pozisyona giriyor, bitiremiyor. Uygulama ağırlığı artmalı.", c: "kotu" };
function gerceklikKat(d, tarih) {
  const olc = (d.olcumler || []).filter((o) => gunFark(tarih, o.tarih) <= 90 && gunFark(tarih, o.tarih) >= 0);
  if (olc.length < 2) return { kat: 1, tavan: 99, olcumSayi: olc.length, bekliyor: true };
  let bek = 0, ger = 0;
  for (const o of olc) { const p = d.oyuncular.find((x) => x.id === o.pid); if (!p) continue; bek += beklenenPuan(o, matchOVR(p)); ger += Number(o.puan) || 0; }
  const kat = bek > 0 ? clamp(ger / bek, 0.7, 1.2) : 1;
  return { kat, tavan: 99 * kat, olcumSayi: olc.length, bekliyor: false };
}

function hamOVR(p) {
  const R = ROLLER[p.rol]; const oz = p.ozellik;
  if (!R || !oz) return p.base;
  let s = 0, w = 0; for (const k in R.ag) { s += (oz[k] || 7) * R.ag[k]; w += R.ag[k]; }
  const rolPuan = w ? (s / w) * 5 : 40;
  /* base uzun vadeli birikimi temsil eder; rol puanı o birikimin bu rolde ne kadarını kullanabildiğini söyler */
  return clamp(p.base * 0.55 + rolPuan * 0.45, 30, 99);
}
const matchOVR = (p) => p._zorla != null ? p._zorla : (p._keskin || 1) * clamp(Math.min(hamOVR(p), p.ovrTavan || 99) + p.form + (p.hazirlik || 0) + (p.akicilikCeza || 0) + (p.taktikEtki || 0) + (p.kondisyon - 70) * 0.12 + (p.moral - 70) * 0.06, 30, 99);
const harmonik = (arr) => arr.length ? arr.length / arr.reduce((s, v) => s + 1 / Math.max(1, v), 0) : 0;
const HAT_AGIRLIK = { ATT: 0.3, MID: 0.3, DEF: 0.3, GK: 0.1 };
function hatGucleri(onbir) {
  const out = {};
  for (const h of HATLAR) { const g = onbir.filter((p) => p.hat === h).map((p) => matchOVR(p)); out[h] = g.length ? harmonik(g) : 0; }
  return out;
}
function takimGucu(onbir) {
  const hg = hatGucleri(onbir);
  let pay = 0, payda = 0;
  for (const h of HATLAR) { if (hg[h] > 0) { pay += HAT_AGIRLIK[h]; payda += HAT_AGIRLIK[h] / hg[h]; } }
  return { takimOVR: payda > 0 ? pay / payda : 0, hatGucu: hg };
}
function enZayifHalka(onbir) {
  if (!onbir.length) return null;
  const zayif = [...onbir].sort((a, b) => matchOVR(a) - matchOVR(b))[0];
  const tam = takimGucu(onbir).takimOVR;
  const digerleri = onbir.filter((p) => p.id !== zayif.id);
  const ref = digerleri.length ? digerleri.reduce((s, p) => s + matchOVR(p), 0) / digerleri.length : matchOVR(zayif);
  const varsayim = onbir.map((p) => (p.id === zayif.id ? { ...p, base: p.base + (ref - matchOVR(p)) } : p));
  const kayip = Math.max(0, takimGucu(varsayim).takimOVR - tam);
  return { oyuncu: zayif, ovr: Math.round(matchOVR(zayif)), kayip: Math.round(kayip) };
}

