  bizBaski: ["{t} sahada üstünlüğü aldı, rakip yarı sahaya yerleşti.", "Baskı {t} tarafında, top ayaklarında duruyor.", "{t} tempoyu yükseltti."],
  rakipBaski: ["{r} oyunu eline aldı, geri çekiliyoruz.", "Baskı {r} tarafında, nefes alamıyoruz.", "{r} ceza sahamıza yükleniyor."],
  dengeli: ["Orta sahada karşılıklı mücadele.", "Oyun dengeli, iki takım da risk almıyor.", "Top ortada gidip geliyor."],
