  if (gun >= 4) secenek.push(`${p.kisaAd} ${gun} gündür aralıksız sahada; formu tesadüf değil.`);
  if (dk7 === 0) secenek.push(`${p.kisaAd} bu hafta hiç antrenman görmedi, oyuna giremiyor.`);
