  const oyuncular2 = kaptan ? oyuncular.map((p) => (p.id === kaptan.id ? p : { ...p, moral: clamp(p.moral + (kaptan.moral - p.moral) * 0.3, 0, 100) })) : oyuncular;
  const tablo = { ...d.tablo };
