  const sira = siramiz(d);
  const bizim = d.tablo[d.kulup.ad] || { p: 0, g: 0, b: 0, m: 0, a: 0, y: 0 };
  const terfi = sira <= 2 && d.kulup.kademe > 1;
  const dusme = sira >= 16 && d.kulup.kademe < 5;
  const rapor = sezonRaporu(d, sira, bizim, terfi, dusme);
  const arsiv = { ...d.arsiv, sezonlar: [...d.arsiv.sezonlar, rapor] };
  if (sira === 1) arsiv.kupalar = [...arsiv.kupalar, { ad: `${KADEME_AD[d.kulup.kademe]} Şampiyonluğu`, sezon: d.sezon.no, kulup: d.kulup.ad }];
  if (terfi) arsiv.terfiler = [...arsiv.terfiler, { sezon: d.sezon.no, nereden: KADEME_AD[d.kulup.kademe], nereye: KADEME_AD[d.kulup.kademe - 1] }];
  const efsaneler = [...arsiv.efsaneler];
  for (const p of d.oyuncular) {
    const ort = p.sezon.mac ? p.sezon.reytingTop / p.sezon.mac : 0;
    if (p.sezon.mac >= 10 && ort >= 8.5 && !efsaneler.some((e) => e.id === p.id)) efsaneler.push({ id: p.id, ad: p.ad, sirtNo: p.sirtNo, sezon: d.sezon.no, ort: Math.round(ort * 10) / 10 });
  }
  arsiv.efsaneler = efsaneler;
  const kademe = clamp(d.kulup.kademe + (terfi ? -1 : 0) + (dusme ? 1 : 0), 1, 5);
  const yeniLig = kademe !== d.kulup.kademe ? ligTasi(kulupLigi(d), kademe < d.kulup.kademe ? "terfi" : "dus") : kulupLigi(d);
  const kulup = kademe !== d.kulup.kademe ? { ...kulupOlustur(kademe, d.sezon.no, yeniLig), yonetimGuveni: 70 } : { ...d.kulup, lig: yeniLig, yonetimGuveni: clamp(d.kulup.yonetimGuveni + (sira <= 5 ? 10 : sira >= 15 ? -10 : 0), 0, 100) };
  const oyuncular = d.oyuncular.map((p) => ({ ...p, kariyer: { ...p.kariyer, formaEmekli: p.kariyer.formaEmekli || efsaneler.some((e) => e.id === p.id) }, sezon: { mac: 0, gol: 0, asist: 0, reytingTop: 0, dk: 0, sari: 0, kirmizi: 0, sakatlikGunu: 0 } }));
  const yeni = { ...d, kulup, oyuncular, arsiv, tablo: {}, sezon: { ...d.sezon, no: d.sezon.no + 1, baslangic: bugun, ertelemeHakki: 3, gelisimProjesi: null, fikstur: [] } };
  yeni.tablo = tabloKur(yeni);
  yeni.sezon.fikstur = fiksturUret(yeni, bugun);
