async function aiDanis(d, bugun, gecmis, soru) {
  const onEk = `${PERSONA}\n\n${aiBaglam(d, bugun)}\n\nTeknik direktör seninle konuşuyor. Kısa, somut, rakama dayalı cevap ver. En fazla 6 cümle.\n\n`;
  const g = (gecmis || []).filter((m) => m && m.metin).slice(-8);
  const mesajlar = [];
  if (g.length === 0) { mesajlar.push({ role: "user", content: onEk + "SORU: " + soru }); }
  else {
    g.forEach((m, i) => {
      const rol = m.rol === "assistant" ? "assistant" : "user";
      const icerik = (i === 0 && rol === "user") ? onEk + "SORU: " + m.metin : m.metin;
      const son2 = mesajlar[mesajlar.length - 1];
      /* rol sırasını koru: aynı rol üst üste gelmesin */
      if (son2 && son2.role === rol) son2.content += "\n\n" + icerik;
      else mesajlar.push({ role: rol, content: icerik });
    });
    if (mesajlar[0].role !== "user") mesajlar.unshift({ role: "user", content: onEk + "Devam edelim." });
    if (mesajlar[mesajlar.length - 1].role === "user") mesajlar.push({ role: "assistant", content: "Dinliyorum hocam." });
    mesajlar.push({ role: "user", content: soru });
  }
  return claude(mesajlar, 900);
}
/* ── Konu anlatımı: takıldığın yeri gerçekten açıklar ── */
async function aiKonuAnlat(d, bugun, ders, konu) {
  return claude([{ role: "user", content: `${PERSONA}\n\n${aiBaglam(d, bugun)}

Teknik direktör "${ders}" dersinde "${konu}" konusunda takıldı. Bu konuyu ÖĞRET.
Futbol metaforunu burada bırak — doğrudan, net ve doğru bir ders anlatımı yap.
Yapı: (1) konunun özü iki cümlede, (2) adım adım mantığı, (3) tek bir örnek, (4) en sık yapılan hata.
Sade Türkçe kullan. Bilmediğin bir şeyi uydurma; emin değilsen söyle.` }], 1400);
}
/* ── Mini sınav: Nate soru üretir, sen çözersin, sonuç antrenman kaydına işlenir ── */
async function aiSinavUret(d, bugun, ders, konu, adet, zorluk) {
  const zad = ["kolay", "orta", "zor"][zorluk - 1];
  const out = await claude([{ role: "user", content: `${PERSONA}

"${ders}" dersinden${konu ? ` "${konu}" konusunda` : ""} ${adet} adet ${zad} seviye çoktan seçmeli soru hazırla.
Her soru 4 şıklı olsun, tek doğru cevabı olsun. Sorular gerçek ve doğru olsun, uydurma bilgi kullanma.
Yalnızca şu JSON'u döndür, başka hiçbir şey yazma:
{"sorular":[{"s":"soru metni","secenek":["A şıkkı","B şıkkı","C şıkkı","D şıkkı"],"dogru":0,"aciklama":"kısa çözüm"}]}
"dogru" alanı doğru şıkkın 0-tabanlı indeksidir.` }], 3000);
  const j = jsonAyikla(out);
  return (j.sorular || []).filter((x) => x && x.s && Array.isArray(x.secenek) && x.secenek.length === 4).slice(0, adet);
}
