class Sinir extends React.Component {
  constructor(p) { super(p); this.state = { h: null, bilgi: null }; }
  static getDerivedStateFromError(e) { return { h: e }; }
  componentDidCatch(e, i) {
    console.error("bölüm:", e, i);
    const yigin = (i && i.componentStack ? String(i.componentStack) : "")
      .split("\n").map((x) => x.trim()).filter(Boolean).slice(0, 6).join(" ← ");
    this.setState({ bilgi: ((e && e.message) || String(e)) + (yigin ? "\n\nKONUM: " + yigin : "") });
  }
  render() {
    if (!this.state.h) return this.props.children;
    return <Panel style={{ boxShadow: `inset 0 0 0 1px ${P.kirmizi}66, ${GOLGE.d2}` }}>
      <Bas ikon="!" sag={<span style={{ ...T.etiket, fontSize: 9.5, color: P.kirmizi }}>hata yakalandı</span>}>Bu bölüm açılamadı</Bas>
      <div style={{ padding: "0 13px" }}>
        <div style={{ color: P.hi, fontSize: 13, lineHeight: 1.65, marginBottom: 10 }}>
          <b style={{ color: P.teal }}>Kayıtların güvende.</b> Sorun yalnızca bu ekranın çiziminde — veri katmanına dokunmadı.
          Başka bir sekmeye geçebilir ya da aşağıdan yeniden deneyebilirsin.</div>
        {this.state.bilgi && <div style={{ fontFamily: FS, fontSize: 11, color: P.lo,
          background: P.derin, border: `1px solid ${P.cizgi}`, borderRadius: R.m, padding: "8px 10px", marginBottom: 10, wordBreak: "break-word" }}>{this.state.bilgi}</div>}
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <Hap dolu onClick={() => this.setState({ h: null, bilgi: null })}>Yeniden dene</Hap>
          <Hap onClick={() => { try { navigator.clipboard.writeText(String(this.state.bilgi || "")); } catch (e) {} }}>Hatayı kopyala</Hap>
        </div>
      </div>
    </Panel>;
  }
}
const KayitCip = ({ durum, son }) => { const m = { bos: ["HAZIR", P.lo, "rgba(255,255,255,0.06)"], yazilliyor: ["KAYDEDİLİYOR", "#2A2116", "#C08D53"], tamam: ["KAYDEDİLDİ", "#16281B", P.yesil], hata: ["KAYIT HATASI", "#F4EDE1", P.kirmizi] }[durum]; return <span style={{ background: m[2], color: m[1], fontFamily: FN, fontWeight: 600, fontSize: 10.5, letterSpacing: 1, padding: "5px 10px", clipPath: CS }}>{m[0]}{son && durum === "tamam" ? ` ${new Date(son).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}` : ""}</span>; };

