function UstBar({ d, bugun, kilitli, simdi, kayit, ileri, genis = false, menuAc, paletAc, geriAl, geriSayi = 0 }) {
  const hafta = Math.floor(gunFark(bugun, d.sezon.baslangic) / 7) + 1;
  const gunAd = ["Pazar", "Pazartesi", "Salı", "Çarşamba", "Perşembe", "Cuma", "Cumartesi"][haftaGunu(bugun)];
  const kalanDk = dkStr(d.ayarlar.macSaati) - simdi;
  let haftaDk = 0; for (let i = 0; i < 7; i++) haftaDk += (d.antrenman[addDays(bugun, -i)] || []).reduce((a, x) => a + x.dakika, 0);
  const oran = clamp(haftaDk / HAFTALIK_DK, 0, 1);
  const Kutucuk = ({ vurgu, ikon, ust, alt }) => (
    <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "7px 14px", clipPath: CS,
      background: vurgu === "yesil" ? "linear-gradient(180deg, rgba(127,169,123,0.16), rgba(127,169,123,0.04))" : "linear-gradient(180deg, rgba(255,255,255,0.07), rgba(255,255,255,0.02))",
      boxShadow: `inset 0 0 0 1px ${vurgu === "yesil" ? "rgba(127,169,123,0.45)" : P.cizgiSert}` }}>
      <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 26, height: 26, clipPath: CS,
        background: vurgu === "yesil" ? "rgba(127,169,123,0.2)" : "rgba(160,138,91,0.18)", fontSize: 14 }}>{ikon}</span>
      <span><span style={{ display: "block", ...T.sayi, fontSize: 16, color: vurgu === "yesil" ? P.yesil : "#F4EDE1", lineHeight: 1.15 }}>{ust}</span>
        <span style={{ display: "block", ...T.etiket, fontSize: 9.5 }}>{alt}</span></span>
    </div>);
  return <header style={{ position: "sticky", top: 0, zIndex: 45, background: "linear-gradient(180deg, rgba(36,30,56,0.97), rgba(26,22,41,0.95))",
    backdropFilter: "blur(14px) saturate(1.3)", borderBottom: `1px solid ${P.cizgi}`,
    boxShadow: "0 1px 0 rgba(255,255,255,0.04), 0 8px 24px rgba(0,0,0,0.34)", padding: genis ? "9px 18px" : "8px 12px" }}>
    <div style={{ display: "flex", alignItems: "center", gap: genis ? 12 : 8, maxWidth: 1720, margin: "0 auto",
      flexWrap: genis ? "nowrap" : "wrap", minWidth: 0 }}>
      {genis && <span style={{ display: "flex", gap: 4, marginRight: 2 }}>
        <button onClick={paletAc} aria-label="Ara (Ctrl+K)" title="Ara · Ctrl+K" className="pes-hap"
          style={{ ...T.hap, minWidth: 30, minHeight: 30, padding: 0, fontSize: 15, color: P.morAcik }}>⌕</button>
        {geriSayi > 0 && <button onClick={geriAl} aria-label="Geri al (Ctrl+Z)" title={`Geri al · ${geriSayi} adım`} className="pes-hap"
          style={{ ...T.hap, minWidth: 30, minHeight: 30, padding: 0, fontSize: 14, color: P.altin }}>⟲</button>}
        {["‹", "›"].map((g, i) => <button key={i} onClick={() => (i ? window.history.forward() : window.history.back())} aria-label={i ? "İleri" : "Geri"}
          className="pes-hap" style={{ ...T.hap, minWidth: 30, minHeight: 30, padding: 0, fontSize: 16, color: P.mid }}>{g}</button>)}</span>}
      {!genis && <button onClick={paletAc} aria-label="Ara" className="pes-hap" style={{ minWidth: 42, minHeight: 42,
        background: "rgba(255,255,255,0.05)", border: `1px solid ${P.cizgiSert}`, borderRadius: 3, cursor: "pointer",
        color: P.morAcik, fontSize: 17 }}>⌕</button>}
      {!genis && <button onClick={menuAc} aria-label="Menü" className="pes-hap" style={{ minWidth: 44, minHeight: 44, display: "flex", flexDirection: "column",
        alignItems: "center", justifyContent: "center", gap: 4, background: "rgba(255,255,255,0.05)", border: `1px solid ${P.cizgiSert}`, borderRadius: 3, cursor: "pointer" }}>
        {[0, 1, 2].map((i) => <span key={i} style={{ width: 17, height: 2, background: P.altin }} />)}</button>}
      <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0, flex: 1 }}>
        <Arma k={d.kimlik} ad={d.kulup.ad} boy={32} />
        {genis && <span style={{ display: "flex", flexDirection: "column", gap: 1, color: P.lo, fontSize: 8, lineHeight: 1 }}><span>▲</span><span>▼</span></span>}
        <div style={{ flex: 1, minWidth: 0, display: "flex", alignItems: "center", gap: 10, minHeight: 42, padding: "0 15px",
          background: "rgba(18,15,31,0.72)", border: `1px solid ${P.cizgi}`, borderRadius: 999, boxShadow: "inset 0 1px 3px rgba(0,0,0,0.35)" }}>
          <span style={{ color: P.lo, fontSize: 13 }}>⌕</span>
          <span style={{ minWidth: 0 }}>
            <span style={{ display: "block", fontFamily: FT, fontWeight: 700, fontSize: 14.5, color: "#F4EDE1", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{d.kulup.ad}</span>
            <span style={{ display: "block", fontSize: 11, color: P.lo, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {KADEME_AD[d.kulup.kademe]} · {siramiz(d)}. sıra · {tdLisans(d).ad} · Sezon {d.sezon.no}</span></span>
        </div>
      </div>
      {genis && <span style={{ width: 1, height: 34, background: P.cizgi }} />}
      {genis && <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "6px 14px", clipPath: CS, background: "rgba(255,255,255,0.04)", boxShadow: `inset 0 0 0 1px ${P.cizgi}`, minWidth: 190 }}>
        <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 28, height: 28, borderRadius: "50%",
          background: `linear-gradient(180deg, ${P.altin}, ${P.altinKoyu})`, color: "#16212B", fontFamily: FN, fontWeight: 700, fontSize: 14 }}>{d.sezon.no}</span>
        <span style={{ flex: 1 }}>
          <span style={{ display: "block", ...T.etiket, fontSize: 10, color: P.mid }}>{haftaDk} / {HAFTALIK_DK} dk</span>
          <span style={{ display: "block", height: 5, marginTop: 4, background: "rgba(255,255,255,0.08)", clipPath: CS }}>
            <span style={{ display: "block", height: "100%", width: `${oran * 100}%`, background: `linear-gradient(90deg, ${P.altinKoyu}, ${P.altin})` }} /></span></span>
      </div>}
      <span style={{ flex: 1 }} />
      <Kutucuk vurgu="yesil" ikon="€" ust={PARA((d.mali || {}).kasa || 0)} alt="Kulüp Kasası" />
      {genis && <div style={{ textAlign: "right", paddingRight: 4 }}>
        <div style={{ ...T.sayi, fontSize: 14, color: P.altin, lineHeight: 1.2 }}>{gunAd} {d.ayarlar.macSaati}</div>
        <div style={{ ...T.sayi, fontSize: 13, color: P.altin, opacity: 0.85 }}>Hafta {hafta}/34</div></div>}
      <KayitCip durum={kayit} son={null} />
      <button className="pes-hap" onClick={ileri} style={{ ...T.hap, ...T.hapDolu, fontSize: 14, fontWeight: 700, letterSpacing: "0.06em",
        minHeight: 42, padding: "0 22px", borderRadius: R.m, display: "inline-flex", alignItems: "center", gap: 8 }}>DEVAM <span style={{ opacity: 0.8 }}>»</span></button>
    </div>
    {!kilitli && kalanDk > 0 && kalanDk <= 120 && <div className="pes-yanip" style={{ ...T.etiket, fontSize: 10, color: P.altin, marginTop: 6, textAlign: genis ? "left" : "center" }}>
      ◷ KADRO KİLİDİNE {Math.floor(kalanDk / 60)}s {kalanDk % 60}dk</div>}
  </header>;
}

function AnaSayfa(props) {
  const { d, bugun, git, kaydet, genis = false, genisXL = false, sutun = 1, kilitli = false } = props;
  const [mSek, setMSek] = useState("hepsi");
  const [haber, setHaber] = useState(0);
  const T2 = useMemo(() => kulupTema(d), [d && d.kulup && d.kulup.ad]);
  const mesajlar = useMemo(() => mesajListesi(d, bugun), [d, bugun]);
  const gorevler = mesajlar.filter((m) => m.tur === "gorev");
  const uyarilar = mesajlar.filter((m) => m.tur === "uyari");
  const gosterilen = mSek === "gorev" ? gorevler : mSek === "uyari" ? uyarilar : mesajlar;
  const tablo = useMemo(() => siraliTablo(d.tablo), [d.tablo]);
  const fiks = useMemo(() => [...(d.sezon.fikstur || []).filter((f) => !f.oynandi).slice(0, 6),
    ...turnuvaFikstur(d, bugun).slice(0, 3)].sort((a, b) => (a.hafta || 0) - (b.hafta || 0)), [d, bugun]);
  const son = (d.maclar || []).slice(-1)[0];
  const sonraki = (d.sezon.fikstur || []).find((f) => !f.oynandi);
  const g = gerceklikKat(d, bugun), c = haftalikCikti(d, bugun);
  /* haber kartları — gerçek veriden manşetler */
  const haberler = useMemo(() => {
    const H = [];
    if (son) H.push({ b: `${d.kulup.ad} ${son.golBiz}-${son.golRak} ${son.rakip}`,
      m: `${son.hikayeAd || "Maç raporu"}. ${son.adam ? son.adam.kisaAd + " sahanın en iyisiydi (" + son.adam.reyting.toFixed(2) + ").": ""} xG ${son.xgBiz} - ${son.xgRak}.`,
      e: ["Maç Raporu", d.kulup.lig ? (LIGLER[d.kulup.lig] || {}).ad : "Lig"], git: ["mac"] });
    if (g.bekliyor) H.push({ b: "Reytingler henüz doğrulanmadı",
      m: "Kulübün açıkladığı reytinglerin sahadaki karşılığı, resmî ölçüm girilene kadar bilinemez. En az iki ölçüm gerekiyor.",
      e: ["Analiz", "Ölçüm"], git: ["kulup", "olcum"] });
    else H.push({ b: `Dönüşüm oranı ${g.kat.toFixed(2)}`,
      m: g.kat < 0.9 ? "Antrenmandaki ilerleme sahaya tam yansımıyor. Seans türü ya da sınav koşulu gözden geçirilmeli."
        : "Antrenmandaki emek sahada karşılığını buluyor. Reytingler güvenilir.",
      e: ["Analiz", `Tavan ${Math.round(g.tavan)}`], git: ["kulup", "olcum"] });
    if (sonraki) H.push({ b: `Sırada ${sonraki.rakip}`,
      m: `${sonraki.evSahibi ? "İç sahada" : "Deplasmanda"} oynanacak. Rakip gücü ${sonraki.rakipOVR}. ${sonraki.derbi ? "Derbi havası şimdiden hissediliyor." : ""}`,
      e: ["Maç Önizleme", `${sonraki.hafta}. Hafta`], git: ["mac"] });
    H.push({ b: `Haftalık çıktı: ${c.dk} dakika`,
      m: `${c.gun} gün çalışıldı, isabet %${Math.round(c.dogruluk * 100)}. ${c.dk >= HAFTALIK_DK * 0.9 ? "Hedef karşılandı." : "Hedefin altında kalındı."}`,
      e: ["Antrenman", "Hafta Raporu"], git: ["bugun"] });
    return H;
  }, [d, bugun]);
  const hb = haberler[haber % haberler.length] || haberler[0];
  const MSEK = [["hepsi", `Hepsi`], ["gorev", `Görevler (${gorevler.length})`], ["uyari", `Uyarılar (${uyarilar.length})`]];

  /* ── SOL: MESAJLAR ── */
  const kMesaj = <section style={{ ...CAM(), borderRadius: R.l, overflow: "hidden",
    boxShadow: `${GOLGE.ic}, inset 0 0 0 1px ${P.cizgi}, ${GOLGE.d2}`, display: "flex", flexDirection: "column" }}>
    <div style={{ padding: "13px 15px 0" }}>
      <h2 style={{ fontFamily: FN, fontWeight: 700, fontSize: 18, color: "#FFF", margin: 0 }}>Mesajlar</h2>
      <div style={{ display: "flex", gap: 5, margin: "11px 0 9px", flexWrap: "wrap" }}>
        {MSEK.map(([k, v]) => <button key={k} className="pes-hap" onClick={() => { Ses.cal("tik"); setMSek(k); }}
          style={{ minHeight: 30, padding: "0 12px", border: "none", borderRadius: 999, cursor: "pointer",
            fontFamily: FT, fontSize: 12.5, fontWeight: mSek === k ? 700 : 500,
            background: mSek === k ? T2.grad : "rgba(255,255,255,0.05)",
            color: mSek === k ? "#FFF" : P.mid }}>{v}</button>)}
      </div>
    </div>
    <div className="td-kaydir" style={{ maxHeight: genis ? 620 : 380, overflowY: "auto", padding: "0 8px 10px" }}>
      <div style={{ ...T.etiket, fontSize: 9, padding: "7px 8px", color: P.lo,
        background: "rgba(255,255,255,0.03)", borderRadius: R.s, margin: "0 0 4px" }}>{kisaTarih(bugun)}</div>
      {gosterilen.length === 0 && <div style={{ padding: "24px 12px", textAlign: "center", color: P.lo, fontSize: 13 }}>
        Bu sekmede mesaj yok.</div>}
      {gosterilen.map((m) => { const [c1] = KART_RENK[m.renk] || KART_RENK.mor;
        return <button key={m.id} className="pes-ray" onClick={() => m.git && git(...m.git)}
          style={{ display: "flex", gap: 11, alignItems: "flex-start", width: "100%", padding: "10px 8px",
            border: "none", background: "transparent", cursor: "pointer", textAlign: "left",
            borderBottom: `1px solid ${P.cizgi}` }}>
          <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 34, height: 34,
            flex: "0 0 34px", borderRadius: "50%", background: `${c1}26`, boxShadow: `inset 0 0 0 1px ${c1}55`,
            color: c1, fontSize: 15 }}>{m.ik}</span>
          <span style={{ flex: 1, minWidth: 0 }}>
            <span style={{ display: "flex", alignItems: "baseline", gap: 6, justifyContent: "space-between" }}>
              <span style={{ fontSize: 11.5, color: P.lo, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{m.ad}</span>
              <span style={{ display: "flex", alignItems: "center", gap: 4, flex: "0 0 auto" }}>
                <span style={{ color: m.tur === "gorev" ? P.altin : m.tur === "uyari" ? P.turuncu : P.yesil, fontSize: 10 }}>
                  {m.tur === "gorev" ? "❗" : m.tur === "uyari" ? "⚠" : "✓"}</span>
                <span style={{ ...T.sayi, fontSize: 11.5, color: P.lo }}>{m.saat}</span></span></span>
            <span style={{ display: "block", fontSize: 13.5, color: P.hi, lineHeight: 1.4, marginTop: 2 }}>{m.baslik}</span>
            <span style={{ display: "block", fontSize: 11.5, color: P.mid, lineHeight: 1.45, marginTop: 2 }}>{m.ozet}</span>
          </span></button>; })}
    </div>
  </section>;

  /* ── ORTA: HABER + KARTLAR + TAKVİM ── */
  const kHaber = <section style={{ position: "relative", overflow: "hidden", borderRadius: R.l, ...CAM(),
    boxShadow: `${GOLGE.ic}, inset 0 0 0 1px ${P.cizgi}, ${GOLGE.d2}` }}>
    <span aria-hidden style={{ position: "absolute", right: "-8%", top: "-30%", width: "58%", height: "170%",
      background: `radial-gradient(closest-side, ${T2.ana}2E, transparent)`, filter: "blur(28px)" }} />
    <button className="pes-ray" onClick={() => git("arsiv")} style={{ display: "flex", alignItems: "center", gap: 8,
      width: "100%", padding: "12px 16px", border: "none", background: "transparent", cursor: "pointer",
      borderBottom: `1px solid ${P.cizgi}`, color: T2.ikinci, fontFamily: FN, fontWeight: 700, fontSize: 15 }}>
      <span style={{ fontSize: 14 }}>◍</span>Bütün Haberlere Bak<span style={{ opacity: 0.6 }}>›</span></button>
    <div style={{ display: "flex", gap: 14, padding: genis ? "18px 18px 12px" : "14px 14px 10px", alignItems: "flex-start" }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <h3 style={{ fontFamily: FN, fontWeight: 700, fontSize: genis ? 22 : 18, color: "#FFF", margin: 0, lineHeight: 1.18 }}>{hb.b}</h3>
        <p style={{ fontSize: 13, color: P.mid, lineHeight: 1.65, margin: "10px 0 0" }}>{hb.m}</p>
        <div style={{ display: "flex", gap: 12, marginTop: 12, ...T.etiket, fontSize: 9.5 }}>
          {hb.e.map((x, i) => <span key={i} style={{ color: i ? P.lo : T2.ikinci }}>{x}</span>)}
          <span style={{ color: P.lo }}>şimdi</span></div>
      </div>
      {genis && <Arma k={d.kimlik} ad={son ? son.rakip : d.kulup.ad} boy={78} />}
    </div>
    <div style={{ display: "flex", gap: 5, padding: "0 16px 14px" }}>
      {haberler.map((_, i) => <button key={i} onClick={() => { Ses.cal("tik"); setHaber(i); }} aria-label={`Haber ${i + 1}`}
        style={{ flex: 1, height: 4, borderRadius: 2, border: "none", cursor: "pointer",
          background: i === haber % haberler.length ? T2.grad : "rgba(255,255,255,0.10)" }} />)}
    </div>
  </section>;

  const kRakip = <Kart renk="mavi" baslik="Sonraki Rakip Takım Raporu" ikon="◈">
    {sonraki ? <>
      <div style={{ display: "flex", alignItems: "center", gap: 11, marginBottom: 11 }}>
        <Arma ad={sonraki.rakip} boy={44} />
        <span style={{ flex: 1, minWidth: 0 }}>
          <span style={{ display: "block", fontFamily: FN, fontWeight: 700, fontSize: 17, color: "#FFF" }}>
            {sonraki.rakip} <span style={{ color: P.lo, fontSize: 13 }}>({sonraki.evSahibi ? "İ" : "D"})</span></span>
          <span style={{ display: "block", fontSize: 11.5, color: P.lo }}>
            {(LIGLER[d.kulup.lig] || {}).ad} · {sonraki.hafta}. hafta</span></span>
        <span style={{ ...T.etiket, fontSize: 9.5, color: P.altin }}>
          {sonraki.tarih === bugun ? "bugün" : gunFark(sonraki.tarih, bugun) + " güne"}</span>
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <Kutu etiket="RAKİP GÜCÜ" deger={sonraki.rakipOVR} renk={P.hi} />
        <Kutu etiket="BİZİM GÜÇ" deger={Math.round(takimGucu(ilkOnbir({ ...d, oyuncular: onizleme(d, bugun) }, "lig").onbir).takimOVR)} renk={T2.ikinci} />
        <Kutu etiket="DİZİLİŞ" deger={d.sezon.formasyon} renk={P.mid} />
      </div>
    </> : <div style={{ fontSize: 12.5, color: P.lo }}>Sırada maç yok.</div>}
  </Kart>;

  const kFikstur = <Kart renk="amber" baslik="Fikstürler" altBaslik={`${fiks.length} karşılaşma`} ikon="▦"
    sag={<Hap onClick={() => git("mac")} style={{ fontSize: 11 }}>Maç Merkezi</Hap>}>
    {fiks.length === 0 ? <div style={{ fontSize: 12.5, color: P.lo }}>Fikstür boş.</div>
      : fiks.slice(0, 5).map((f) => <div key={f.no} style={{ display: "flex", alignItems: "center", gap: 9,
        minHeight: 38, borderBottom: `1px solid ${P.cizgi}` }}>
        <span style={{ ...T.etiket, fontSize: 9, width: 54, flex: "0 0 54px",
          color: f.turnuva ? P.altin : P.lo }}>{f.turnuva ? TURNUVALAR[f.turnuva].kisa : "LİG"}</span>
        <Arma ad={f.rakip} boy={24} />
        <span style={{ flex: 1, minWidth: 0, fontSize: 12.5, color: P.hi, whiteSpace: "nowrap",
          overflow: "hidden", textOverflow: "ellipsis" }}>{f.rakip}</span>
        <span style={{ ...T.etiket, fontSize: 9, color: P.lo }}>{f.evSahibi ? "İ" : "D"}</span>
        <span style={{ ...T.sayi, fontSize: 12.5, color: P.mid, width: 42, textAlign: "right" }}>{d.ayarlar.macSaati}</span>
      </div>)}
  </Kart>;

  /* takvim ızgarası */
  const kTakvim = <Kart renk="mor" baslik={`${new Date(bugun + "T00:00:00").getFullYear()} Takvimi`} altBaslik="Antrenman ve maç günleri" ikon="▦">
    <div style={{ display: "grid", gridTemplateColumns: "repeat(7, minmax(0,1fr))", gap: 3 }}>
      {["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"].map((x) => <span key={x}
        style={{ ...T.etiket, fontSize: 9, textAlign: "center", padding: "3px 0", color: P.lo }}>{x}</span>)}
      {(() => {
        const bas = addDays(bugun, -((haftaGunu(bugun) + 6) % 7));
        return Array.from({ length: 21 }, (_, i) => {
          const t = addDays(bas, i);
          const se = d.antrenman[t] || [];
          const mac = (d.sezon.fikstur || []).find((f) => f.tarih === t);
          const bugunMu = t === bugun;
          const dk = se.reduce((a, x) => a + x.dakika, 0);
          return <span key={t} style={{ minHeight: genis ? 52 : 42, borderRadius: R.s, padding: "3px 4px",
            background: bugunMu ? T2.grad : mac ? "rgba(255,182,39,0.10)" : "rgba(255,255,255,0.028)",
            boxShadow: `inset 0 0 0 1px ${bugunMu ? "transparent" : P.cizgi}`, overflow: "hidden" }}>
            <span style={{ display: "block", ...T.sayi, fontSize: 11, color: bugunMu ? "#FFF" : P.mid }}>{t.slice(-2)}</span>
            {se.length > 0 && <span style={{ display: "flex", gap: 1.5, marginTop: 2, flexWrap: "wrap" }}>
              {se.slice(0, 3).map((_, j) => <span key={j} style={{ width: 4, height: 4, borderRadius: 1,
                background: bugunMu ? "#FFF" : P.teal }} />)}</span>}
            {dk > 0 && genis && <span style={{ display: "block", ...T.sayi, fontSize: 8.5,
              color: bugunMu ? "rgba(255,255,255,0.85)" : P.lo }}>{dk}dk</span>}
            {mac && <span style={{ display: "block", ...T.etiket, fontSize: 9, color: bugunMu ? "#FFF" : P.altin,
              whiteSpace: "nowrap", overflow: "hidden" }}>{mac.oynandi ? "OYNANDI" : "MAÇ"}</span>}
          </span>; });
      })()}
    </div>
  </Kart>;

  /* ── SAĞ: MAÇ TAKVİMİ + PUAN DURUMU ── */
  const kMacTakvim = <Kart renk="teal" baslik="Maç Takvimi" altBaslik="Yaklaşan karşılaşmalar" ikon="◷">
    {fiks.slice(0, 7).map((f) => <div key={"mt" + f.no} style={{ display: "flex", alignItems: "center", gap: 8,
      minHeight: 36, borderBottom: `1px solid ${P.cizgi}` }}>
      <span style={{ ...T.sayi, fontSize: 11, width: 46, flex: "0 0 46px", color: P.lo }}>{f.tarih ? f.tarih.slice(5).replace("-", "/") : "—"}</span>
      <span style={{ ...T.etiket, fontSize: 9, padding: "2px 5px", borderRadius: 3, flex: "0 0 auto",
        background: f.turnuva ? "rgba(255,182,39,0.16)" : "rgba(45,212,191,0.14)",
        color: f.turnuva ? P.altin : P.teal }}>{f.turnuva ? TURNUVALAR[f.turnuva].kisa : "Lig"}</span>
      <Arma ad={f.rakip} boy={20} />
      <span style={{ flex: 1, minWidth: 0, fontSize: 12, color: P.hi, whiteSpace: "nowrap",
        overflow: "hidden", textOverflow: "ellipsis" }}>{f.rakip}</span>
      <span style={{ ...T.etiket, fontSize: 9, color: P.lo }}>{f.evSahibi ? "İ" : "D"}</span>
      <span style={{ ...T.sayi, fontSize: 11.5, color: P.mid }}>{d.ayarlar.macSaati}</span>
    </div>)}
  </Kart>;

  const kTablo = <Kart renk="limon" baslik="Puan Durumu" altBaslik={(LIGLER[d.kulup.lig] || {}).ad || "Lig"} ikon="▦">
    <div style={{ display: "flex", gap: 5, ...T.etiket, fontSize: 9, paddingBottom: 4, borderBottom: `1px solid ${P.cizgiSert}` }}>
      <span style={{ width: 18, flex: "0 0 18px" }}>Poz</span>
      <span style={{ flex: 1 }}>Takım</span>
      {["Oyn", "G", "B", "M", "AV", "Puan"].map((x) => <span key={x} style={{ width: x === "Puan" ? 30 : 20,
        flex: `0 0 ${x === "Puan" ? 30 : 20}px`, textAlign: "right" }}>{x}</span>)}
    </div>
    {tablo.map((x, i) => { const biz = x.ad === d.kulup.ad;
      const bant = i < 2 ? P.mor : i < 4 ? P.turuncu : i < 6 ? P.yesil : i >= tablo.length - 3 ? P.kirmizi : "transparent";
      return <div key={x.ad} style={{ display: "flex", alignItems: "center", gap: 5, minHeight: 26,
        borderBottom: `1px solid ${P.cizgi}`, background: biz ? `${T2.ana}1C` : "transparent" }}>
        <span style={{ width: 18, flex: "0 0 18px", display: "flex", alignItems: "center", gap: 3 }}>
          <span style={{ width: 2, height: 14, borderRadius: 1, background: bant }} />
          <span style={{ ...T.sayi, fontSize: 11, color: P.lo }}>{i + 1}</span></span>
        <Arma ad={x.ad} boy={16} />
        <span style={{ flex: 1, minWidth: 0, fontSize: 11.5, fontWeight: biz ? 700 : 400,
          color: biz ? T2.ikinci : P.mid, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{x.ad}</span>
        {[x.o, x.g, x.b, x.m, x.a - x.y].map((v, j) => <span key={j} style={{ ...T.sayi, fontSize: 11,
          width: 20, flex: "0 0 20px", textAlign: "right", color: P.lo }}>{v}</span>)}
        <span style={{ ...T.sayi, fontSize: 12, width: 30, flex: "0 0 30px", textAlign: "right",
          color: biz ? "#FFF" : P.hi, fontWeight: 700 }}>{x.p}</span>
      </div>; })}
    <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 8, ...T.etiket, fontSize: 9 }}>
      {[["Şampiyonlar Ligi", P.mor], ["Avrupa Ligi", P.turuncu], ["Konferans Ligi", P.yesil], ["Düşme", P.kirmizi]]
        .map(([ad, c1]) => <span key={ad} style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
          <span style={{ width: 2, height: 9, background: c1 }} />{ad}</span>)}
    </div>
  </Kart>;

  const hamle = <HamleKarti d={d} bugun={bugun} kilitli={kilitli} git={git} kaydet={kaydet} genis={genis} />;
  const kBakim = <BakimPaneli d={d} bugun={bugun} git={git} genis={genis} />;
  const kGorev = <GorevPaneli d={d} kaydet={kaydet} bugun={bugun} git={git} genis={genis} kompakt />;
  const kHizli = <HizliKayit d={d} bugun={bugun} kaydet={kaydet} genis={genis} />;
  const kKuyruk = <TekrarKuyrugu d={d} bugun={bugun} kaydet={kaydet} git={git} genis={genis} />;
  if (sutun >= 3) return <>{hamle}{kHizli}<div style={{ display: "grid", gap: 13,
    gridTemplateColumns: "minmax(0,0.86fr) minmax(0,1.28fr) minmax(0,0.94fr)" }}>
    <div style={SUTUN}>{kMesaj}</div>
    <div style={SUTUN}>{kHaber}<div style={IZGARA(2)}>{kRakip}{kFikstur}</div>{kTakvim}</div>
    <div style={SUTUN}>{kGorev}{kMacTakvim}{kTablo}{kKuyruk}</div></div></>;
  if (sutun === 2) return <>{hamle}{kHizli}<div style={IZGARA(2)}>
    <div style={SUTUN}>{kHaber}{kMesaj}{kTakvim}</div>
    <div style={SUTUN}>{kGorev}{kRakip}{kFikstur}{kMacTakvim}{kTablo}{kKuyruk}</div></div></>;
  return <div style={SUTUN}>{hamle}{kHizli}{kGorev}{kHaber}{kRakip}{kMesaj}{kFikstur}{kMacTakvim}{kTablo}{kTakvim}{kKuyruk}</div>;
}

/* yatay kaydırmalı, yapışkan sekme şeridi — her ekranda aynı */
function Serit2({ sekmeler, aktif, sec, ust }) {
  return <div style={{ position: "sticky", top: ust || 0, zIndex: 20, marginBottom: 13,
    background: "linear-gradient(180deg, rgba(23,19,39,0.98) 76%, rgba(23,19,39,0))", borderBottom: `1px solid ${P.cizgi}` }}>
    <div className="td-kaydir" style={{ display: "flex", gap: 0, overflowX: "auto" }}>
      {sekmeler.map(([k, v]) => { const a = aktif === k; return (
        <button key={k} className="pes-ray" onClick={() => sec(k)} aria-current={a ? "true" : undefined}
          style={{ flex: "0 0 auto", minHeight: 40, padding: "0 15px", border: "none", background: "transparent", cursor: "pointer",
            color: a ? "#FFFFFF" : P.lo, fontFamily: FT, fontSize: 14, fontWeight: a ? 700 : 500, whiteSpace: "nowrap",
            borderBottom: `2.5px solid ${a ? P.morAcik : "transparent"}`, transition: "color .15s ease" }}>
          {v}<span style={{ marginLeft: 5, fontSize: 9, opacity: 0.55 }}>▾</span></button>); })}
    </div></div>;
}
/* katlanabilir bölüm — uzun ekranları toparlar */
function Katla({ baslik, children, acikBasla = true }) {
  const [a, setA] = useState(acikBasla);
  return <div style={{ marginBottom: 13 }}>
    <button className="pes-ray" onClick={() => setA(!a)} style={{ display: "flex", alignItems: "center", justifyContent: "space-between",
      width: "100%", minHeight: 44, padding: "0 14px", border: "none", cursor: "pointer", clipPath: CS, marginBottom: a ? 8 : 0,
      background: "linear-gradient(90deg, rgba(160,138,91,0.16), rgba(160,138,91,0.02))", boxShadow: `inset 0 0 0 1px ${P.cizgi}` }}>
      <span style={{ fontFamily: FN, fontWeight: 600, fontSize: 14, letterSpacing: 1.3, color: P.altin, textTransform: "uppercase" }}>{baslik}</span>
      <span style={{ color: P.lo, fontSize: 13, transform: a ? "rotate(180deg)" : "none", transition: "transform .18s" }}>▾</span></button>
    {a && children}</div>;
}
/* mobil çekmece menü — tüm ekranlara erişim */
function MobilMenu({ acik, kapat, sekme, altSekme, git, d, bugun }) {
  if (!acik) return null;
  return <div onClick={kapat} style={{ position: "fixed", inset: 0, zIndex: 90, background: "rgba(8,14,22,0.72)", backdropFilter: "blur(3px)" }}>
    <div onClick={(e) => e.stopPropagation()} style={{ position: "absolute", top: 0, bottom: 0, left: 0, width: "min(84vw, 320px)", overflowY: "auto",
      background: "linear-gradient(180deg, #1E2C39, #131D26)", boxShadow: `inset -1px 0 0 ${P.cizgiSert}`, padding: "16px 12px calc(16px + env(safe-area-inset-bottom))" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
        <Arma k={d.kimlik} ad={d.kulup.ad} boy={38} />
        <span style={{ flex: 1, minWidth: 0 }}>
          <span style={{ display: "block", fontFamily: FN, fontWeight: 600, fontSize: 16, color: "#F4EDE1" }}>{d.kulup.ad}</span>
          <span style={{ display: "block", ...T.etiket, fontSize: 10 }}>{KADEME_AD[d.kulup.kademe]} · {siramiz(d)}. sıra</span></span>
        <button onClick={kapat} aria-label="Menüyü kapat" style={{ minWidth: 44, minHeight: 44, background: "transparent", border: "none", color: P.mid, fontSize: 22, cursor: "pointer" }}>×</button>
      </div>
      {MENU.map((m) => { const a = sekme === m.id && (m.alt ? altSekme === m.alt : !altSekme || m.id !== "kulup"); return (
        <button key={menuAnahtar(m)} className="pes-ray" onClick={() => { git(m.id, m.alt); kapat(); }} style={{ position: "relative", display: "block", width: "100%",
          textAlign: "left", border: "none", cursor: "pointer", minHeight: 50, padding: "0 16px", marginBottom: 4, clipPath: CS,
          background: a ? "linear-gradient(90deg, rgba(160,138,91,0.26), rgba(160,138,91,0.03))" : "rgba(255,255,255,0.028)",
          color: a ? P.altin : P.hi, fontFamily: FT, fontSize: 15.5 }}>
          {a && <span style={{ position: "absolute", left: 0, top: 8, bottom: 8, width: 3, background: P.altin, boxShadow: `0 0 10px ${P.altin}` }} />}
          {m.ad}</button>); })}
      <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${P.cizgi}` }}><Sinir><MiniOzet d={d} bugun={bugun} /></Sinir></div>
    </div></div>;
}
/* uzun ekranlarda başa dön */
function YukariBtn({ genis = false }) {
  const [gor, setGor] = useState(false);
  useEffect(() => { const f = () => setGor(window.scrollY > 640); window.addEventListener("scroll", f, { passive: true }); return () => window.removeEventListener("scroll", f); }, []);
  if (!gor) return null;
  return <button onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })} aria-label="Yukarı dön"
    style={{ position: "fixed", right: 14, bottom: genis ? 20 : 74, zIndex: 35, width: 46, height: 46, clipPath: CS, border: "none", cursor: "pointer",
      background: "linear-gradient(180deg, rgba(24,28,46,0.94), rgba(10,12,22,0.96))", boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.12), 0 8px 22px rgba(0,0,0,0.5)",
      color: "var(--vurgu)", display: "flex", alignItems: "center", justifyContent: "center" }}><Ikon ad="ileri" boy={20} kalin={2.4} style={{ transform: "rotate(-90deg)" }} /></button>;
}

/* ══════════════════════════ UYGULAMA ══════════════════════════ */
/* Kırılma noktaları — Samsung Tab S10 FE hedefli (dikey ~720px, yatay ~1152px CSS) */
/* Kabın GERÇEK genişliğini ölçer. window.innerWidth artifact çerçevesinde
   yanıltıcı olabiliyor; ResizeObserver kendi köküne bakar. */
function useGenislik(kokRef) {
  const oku = () => {
    if (kokRef && kokRef.current && kokRef.current.clientWidth > 40)
      return { w: kokRef.current.clientWidth, h: kokRef.current.clientHeight || 720 };
    if (typeof window !== "undefined") return { w: window.innerWidth, h: window.innerHeight };
    return { w: 1152, h: 720 };
  };
  const [o, setO] = useState({ w: 1152, h: 720 });
  useEffect(() => {
    let t;
    const f = () => { clearTimeout(t); t = setTimeout(() => setO(oku()), 60); };
    f();
    let ro = null;
    if (typeof ResizeObserver !== "undefined" && kokRef && kokRef.current) {
      ro = new ResizeObserver(f); ro.observe(kokRef.current);
    }
    window.addEventListener("resize", f); window.addEventListener("orientationchange", f);
    return () => { clearTimeout(t); if (ro) ro.disconnect();
      window.removeEventListener("resize", f); window.removeEventListener("orientationchange", f); };
  }, [kokRef && kokRef.current]);
  const w = o.w;
  const dar = w < 560;                  /* telefon / dar artifact paneli */
  const orta = w >= 560 && w < 880;     /* tablet dikey */
  const genis = w >= 880;               /* tablet yatay ve üstü */
  const genisXL = w >= 1320;            /* geniş masaüstü */
  const sutun = genisXL ? 3 : genis ? 2 : orta ? 2 : 1;
  const rayGenislik = genisXL ? 190 : genis ? 156 : 0;
  return { w, h: o.h, dar, orta, genis, genisXL, sutun, rayGenislik, yatay: w > o.h };
}
/* güvenli ızgara: minmax(0,·) sütunların içerikten dar olmasına izin verir → taşma biter */
const IZGARA = (n, bosluk = 12) => ({ display: "grid", gridTemplateColumns: `repeat(${n}, minmax(0, 1fr))`, gap: bosluk, alignItems: "start" });
const SUTUN = { display: "grid", gap: 12, minWidth: 0 };
/* ══════════════════════════════════════════════════════════════════════
   ARENA · v70 — OYUN KATMANI
   Uygulamanın kabuğu: seviye, oyuncu kartı, sezon bileti, paketler,
   koleksiyon ve günlük hikâyeler.

   TEK KURAL: ödülün tamamı çalışmadan doğar. Uygulamada geçirilen süre
   hiçbir şey kazandırmaz. Sonsuz akış yok, satın alma yok, olasılıklar açık.

   XP ve kazanılan paketler kayıttan TÜRETİLİR, saklanmaz. Böylece geri al,
   seans silme ya da göç hiçbir zaman çift sayım veya kayıp üretmez. Saklanan
   tek şey kullanıcının seçimleridir: açılan paketler, toplanan ödüller,
   giyilen kozmetikler. Paket içeriği paket kimliğinden tohumlanır: geri alıp
   yeniden açmak aynı sonucu verir, "yeniden zar atma" yoktur.
   ══════════════════════════════════════════════════════════════════════ */

/* ── 1 · XP KURALLARI ── her puanın kaynağı açık */
const XP = { dk: 10, dogru: 4, rutin: 20, uyku: 60, galibiyet: 150, beraberlik: 50, hata: 60,
  konu: { islendi: 100, tekrar: 250, oturdu: 500 } };
const XP_ACIKLAMA = [
  ["Çalışma dakikası", "dakika başına 10 XP"], ["Doğru soru", "doğru başına 4 XP"],
  ["Konu kademesi", "İşlendi 100 · Tekrar 250 · Oturdu 500 · günde en çok 500"], ["Çözülen hata", "60 XP"],
  ["Maç", "galibiyet 150 · beraberlik 50"], ["Alışkanlık", "işaret başına 20 XP"], ["Hedefte uyku", "gece başına 60 XP"],
];
const GUN_AD_UZUN = ["Pazar", "Pazartesi", "Salı", "Çarşamba", "Perşembe", "Cuma", "Cumartesi"];
const AY_AD = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
const arenaTarih = (t) => { try { const x = parseD(t); return `${x.getDate()} ${AY_AD[x.getMonth()]} ${GUN_AD_UZUN[x.getDay()]}`; } catch (e) { return t; } };
const binlik = (n) => Math.round(Number(n) || 0).toLocaleString("tr-TR");


/* ── 2 · SEVİYE ── ilk seviyeler hızlı, sonrası anlamlı: n → n+1 = 600 + 100·n XP */
const seviyeMaliyet = (n) => 600 + 100 * n;
function seviyeBul(xp) {
  let sv = 1, kalan = Math.max(0, Math.floor(Number(xp) || 0));
  while (sv < 999 && kalan >= seviyeMaliyet(sv)) { kalan -= seviyeMaliyet(sv); sv++; }
  const gerek = seviyeMaliyet(sv);
  return { seviye: sv, icinde: kalan, gerek, oran: kalan / gerek, eksik: gerek - kalan };
}

