/* aylık sezon kartı — her ay kendine ait bir renk */
function sezonKartTasarim(ay) {
  const [y, a] = String(ay || "2026-01").split("-").map(Number);
  const h = ((a || 1) * 47 + (y || 2026) * 13) % 360;
  return KT(`${AY_AD[((a || 1) - 1) % 12]} ${y} · Sezon Efsanesi`,
    `linear-gradient(168deg,hsl(${h},62%,9%) 0%,hsl(${h},70%,28%) 44%,hsl(${(h + 40) % 360},78%,52%) 78%,hsl(${(h + 60) % 360},90%,74%) 100%)`,
    `linear-gradient(160deg,#FFFFFF,hsl(${(h + 50) % 360},90%,70%),#FFFFFF)`,
    "#FFFFFF", "rgba(255,255,255,0.74)", `hsl(${(h + 50) % 360},100%,82%)`, `hsla(${(h + 40) % 360},90%,60%,0.7)`, "isin");
}

