/* ── 7 · OYUNCU KARTI ── altı özellik, hepsi son haftaların gerçek verisinden */
const KART_OZ = [
  ["HAC", "Hacim", "Son 14 günün toplam dakikası · günde 150 dk = 99"],
  ["SÜR", "Süreklilik", "Son 28 günde en az 15 dk çalışılan gün · 24 gün = 99"],
  ["İSB", "İsabet", "Son 30 günde soru isabeti · %40 → 40, %95 → 99"],
  ["ODK", "Odak", "Ortalama seans süresi · 50 dk ve üstü = 99"],
  ["DNG", "Denge", "Dakikanın dersler arasına dağılımı · eşit dağılım = 99"],
  ["RİT", "Ritim", "Uyku hedefine yakınlık · hedefte = 99"],
];
function oyuncuKartVeri(d, bugun) {
  const A = d.antrenman || {};
  const gunler = (n) => Array.from({ length: n }, (_, i) => addDays(bugun, -i));
  const gunDk = (t) => (A[t] || []).reduce((a, x) => a + (Number(x && x.dakika) || 0), 0);
  const d14 = gunler(14), d28 = gunler(28), d30 = gunler(30);
  const dk14 = d14.reduce((a, t) => a + gunDk(t), 0);
  const st = {};
  st["HAC"] = 40 + 59 * clamp(dk14 / (14 * 150), 0, 1);
  const aktif = d28.filter((t) => gunDk(t) >= 15).length;
  st["SÜR"] = 40 + 59 * clamp(aktif / 24, 0, 1);
  let sq = 0, dg = 0;
  for (const t of d30) for (const s of A[t] || []) { const n = Number(s && s.soru) || 0; if (n) { sq += n; dg += n * clamp(Number(s.dogruluk) || 0, 0, 100) / 100; } }
  st["İSB"] = sq ? 40 + 59 * clamp((dg / sq - 0.4) / 0.55, 0, 1) : 48;
  let sn = 0, sdk = 0; const dag = {};
  for (const t of d14) for (const s of A[t] || []) { if (!s) continue; sn++; const m = Number(s.dakika) || 0; sdk += m; dag[s.pid] = (dag[s.pid] || 0) + m; }
  st["ODK"] = sn ? 40 + 59 * clamp((sdk / sn - 15) / 35, 0, 1) : 45;
  const v = Object.values(dag).filter((x) => x > 0), top = v.reduce((a, x) => a + x, 0);
  const H = top ? -v.reduce((a, x) => a + (x / top) * Math.log(x / top), 0) : 0;
  const ligN = Math.max(2, Math.min(8, (d.oyuncular || []).filter((p) => p.kol === "lig").length));
  st["DNG"] = top ? 40 + 59 * clamp(H / Math.log(ligN), 0, 1) : 45;
  let rit = 52;
  try { const uo = uykuOzet(d, bugun); const h = Number(ritimAl(d).uykuHedef) || 7.5;
    if (uo && uo.n) rit = 40 + 59 * clamp(1 - Math.max(0, h - uo.ort) / 2, 0, 1); } catch (e) {}
  st["RİT"] = rit;
  for (const k in st) st[k] = Math.round(clamp(st[k], 1, 99));
  const ovr = Math.round(st["HAC"] * 0.22 + st["SÜR"] * 0.24 + st["İSB"] * 0.16 + st["ODK"] * 0.12 + st["DNG"] * 0.12 + st["RİT"] * 0.14);
  return { ovr, st };
}

/* ── 8 · KAZANILAN PAKETLER ── türetilir; açılmış olanlar kimlikle işaretlenir */
const SERI_ESIK = [3, 7, 14, 21, 30, 45, 60, 90, 120, 180, 270, 365];
const PAKET_ESIK = { ilk: 25, dilim: 75, dilimAzami: 3, mesai: 180 };
function seriKosulari(gunluk) {
  const t = Object.keys(gunluk).filter((x) => gunluk[x].dk >= 15).sort();
  const out = []; let bas = null, onceki = null, n = 0;
  for (const x of t) {
    if (onceki && gunFark(x, onceki) === 1) { n++; } else { if (bas) out.push({ bas, uzun: n }); bas = x; n = 1; }
    onceki = x;
  }
  if (bas) out.push({ bas, uzun: n });
  return out;
}

/* ── 9 · SEZON BİLETİ ── takvim ayı = sezon · 40 kademe · kademe başına 1.200 XP */
const SEZON_KADEME = 40, SEZON_XP = 1200;
function sezonOdul(ay, k) {
  const [y, a] = String(ay).split("-").map(Number); const ix = (y || 0) * 12 + (a || 0);
  if (k === 40) return { tur: "kozmetik", id: "kt-sezon-" + ay };
  if (k === 35) return { tur: "kozmetik", id: SEZON_VURGU[ix % SEZON_VURGU.length] };
  if (k === 25) return { tur: "kozmetik", id: SEZON_LOBI[ix % SEZON_LOBI.length] };
  if (k === 15) return { tur: "kozmetik", id: SEZON_UNVAN[ix % SEZON_UNVAN.length] };
  if (k % 10 === 0) return { tur: "paket", paket: "elit" };
  if (k % 5 === 0) return { tur: "paket", paket: "altin" };
  if (k % 2 === 0) return { tur: "paket", paket: "bronz" };
  return { tur: "jeton", adet: 10 + Math.floor(k / 10) * 5 };
}

/* ── 10 · PAKET AÇMA ── tohumlu, acıma sayaçlı, yenilik korumalı */
function agirlikliSec(ag, rng) {
  const e = Object.entries(ag); const top = e.reduce((a, [, v]) => a + v, 0);
  let r = rng() * top;
  for (const [k, v] of e) { r -= v; if (r <= 0) return k; }
  return e[e.length - 1][0];
}
const setTamamMi = (kartlar, sid) => KOLEKSIYON.filter((k) => k.set === sid).every((k) => (kartlar[k.id] || 0) > 0);
function kartTakas(d, kartId, bugun) {
  const o = oyunGoc(d); const k = KOLEKSIYON_ID[kartId];
  if (!k || (o.kartlar[kartId] || 0) > 0) return d;
  const bedel = TAKAS_BEDEL[k.nadir]; if (o.jeton < bedel) return d;
  let o2 = { ...o, jeton: o.jeton - bedel, kartlar: { ...o.kartlar, [kartId]: 1 } };
  o2 = setOdulleriniVer(o2, bugun, null);
  return { ...d, oyun: o2 };
}
function hikayeGoruldu(d, bugun, id) {
  const o = oyunGoc(d); const g = o.hikaye[bugun] || [];
  if (g.includes(id)) return d;
  const yeni = {}; for (const t of Object.keys(o.hikaye)) if (gunFark(bugun, t) < 4) yeni[t] = o.hikaye[t];
  yeni[bugun] = [...g, id];
  return { ...d, oyun: { ...o, hikaye: yeni } };
}

/* ── 11 · DURUM ÖZETİ ── tek geçişte hesaplanır, aynı kayıt nesnesi için önbellekten döner */
const OYUN_ONBELLEK = typeof WeakMap !== "undefined" ? new WeakMap() : null;
/* ikinci katman: oyunu etkileyen alanların hiçbiri değişmediyse (not yazmak, müzik ayarı gibi) son sonuç aynen döner */
let OYUN_SON = null;
function oyunDurum(d, bugun) {
  if (!d) return null;
  if (OYUN_ONBELLEK) { const c = OYUN_ONBELLEK.get(d); if (c && c.bugun === bugun) return c.v; }
  const k = [d.oyun, d.antrenman, d.ayarlar, d.aliskanliklar, d.uyku, d.maclar, d.konular, d.hatalar, d.anlatmalar, d.kelimeler, d.oyuncular, d.arsiv, d.kulup, d.rotasyon, d.sezon, d.konuAlt, bugun];
  let v = null;
  if (OYUN_SON && OYUN_SON.k.length === k.length && OYUN_SON.k.every((x, i) => x === k[i])) v = OYUN_SON.v;
  else { try { v = oyunHesapla(d, bugun); } catch (e) { console.error("oyun katmanı:", e); v = null; } if (v) OYUN_SON = { k, v }; }
  if (OYUN_ONBELLEK && v) OYUN_ONBELLEK.set(d, { bugun, v });
  return v;
}

