/* ══════════════════════════════════════════════════════════════════════
   ARENA 2.0 · v71 — DOLAP
   Sekiz kozmetik türü: kart tasarımı, unvan, lobi teması, vurgu rengi,
   profil çerçevesi, kart rozeti, kutlama efekti ve soyunma odası afişi.
   Kaynaklar açıkça etiketlidir: paket, set, sezon, kupa, yol, lig, mağaza.
   ══════════════════════════════════════════════════════════════════════ */
const hexRgba = (h, a) => { const c = String(h || "#FFFFFF").replace("#", ""); const n = parseInt(c.length === 3 ? c.split("").map((x) => x + x).join("") : c.slice(0, 6), 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`; };
const acikRenk = (h) => { const c = String(h || "").replace("#", ""); if (c.length < 6) return false;
  return (parseInt(c.slice(0, 2), 16) * 299 + parseInt(c.slice(2, 4), 16) * 587 + parseInt(c.slice(4, 6), 16) * 114) / 1000 > 150; };
/* KD · dört duraklı zemin + çok duraklı kenar; metin rengi açık/koyu otomatik soluklaşır */
const KD = (ad, z, k, yazi, vurgu, desen, aci = 168) => KT(ad, `linear-gradient(${aci}deg,${z[0]} 0%,${z[1]} 40%,${z[2]} 72%,${z[3]} 100%)`,
  `linear-gradient(160deg,${k.join(",")},${k[0]})`, yazi, acikRenk(yazi) ? "rgba(255,255,255,0.72)" : "rgba(0,0,0,0.64)", vurgu, hexRgba(vurgu, 0.55), desen);

