/* ── 9 · SÖZ ALBÜMÜ · 192 kart: tarihî sözler + soyunma odasının özgün sözleri ── */
const nadirHash = (s) => { const h = hashStr("nadir|" + s) % 100; return h < 4 ? "efsane" : h < 17 ? "destansi" : h < 45 ? "nadir" : "siradan"; };
const SOZ_KART = [
  ...SOZ_TARIHI.map(([metin, kaynak, tema]) => ({ id: "sz-" + hashStr(metin).toString(36), metin, kaynak, tema, tarihi: true })),
  ...SOZ_OZGUN.map(([metin, tema]) => ({ id: "sz-" + hashStr(metin).toString(36), metin, kaynak: "Soyunma odası", tema, tarihi: false })),
].map((x) => ({ ...x, nadir: nadirHash(x.id) }));
const SOZ_KART_ID = Object.fromEntries(SOZ_KART.map((x) => [x.id, x]));

/* ── 10 · KULÜP ARMALARI ALBÜMÜ · 16 lig × 18 kulüp = 288 ── */
const ARMA_KART = [];
for (const [lig, L] of Object.entries(LIGLER)) (L.takim || []).forEach((ad, i) => {
  const nadir = L.itibar >= 5 ? (i < 3 ? "efsane" : i < 8 ? "destansi" : "nadir") : L.itibar === 4 ? (i < 3 ? "destansi" : i < 9 ? "nadir" : "siradan") : (i < 3 ? "nadir" : "siradan");
  ARMA_KART.push({ id: ad, ad, lig, ligAd: L.ad, ulke: L.ulke, nadir, sira: i });
});
const ARMA_KART_ID = Object.fromEntries(ARMA_KART.map((x) => [x.id, x]));
