  const out = [];
  const koz1 = nadirSec({ siradan: 30, nadir: 45, destansi: 20, efsane: 5 }, 0);
  const kozA = sirala(kozPaketHavuzu(koz1), bugun + "a"); const k1 = kozA.find((id) => !o.kozmetik[id]) || kozA[0];
  if (k1) out.push({ slot: 0, tip: "kozmetik", id: k1, nadir: koz1, fiyat: MAGAZA_FIYAT.koz[koz1] });
  const koz2 = nadirSec({ siradan: 25, nadir: 45, destansi: 25, efsane: 5 }, 1);
  const kozB = sirala(kozPaketHavuzu(koz2).filter((id) => !k1 || KOZMETIK[id].tur !== KOZMETIK[k1].tur), bugun + "b"); const k2 = kozB.find((id) => !o.kozmetik[id]) || kozB[0];
  if (k2) out.push({ slot: 1, tip: "kozmetik", id: k2, nadir: koz2, fiyat: MAGAZA_FIYAT.koz[koz2] });
  const gn = nadirSec({ siradan: 40, nadir: 40, destansi: 17, efsane: 3 }, 2);
  const gl = sirala(GUC_ID.filter((id) => GUC[id].nadir === gn), bugun + "g");
  if (gl.length) out.push({ slot: 2, tip: "guc", id: gl[0], nadir: gn, fiyat: MAGAZA_FIYAT.guc[gn] });
  const kn = nadirSec({ nadir: 60, destansi: 35, efsane: 5 }, 3);
  const kl = sirala(KOLEKSIYON.filter((k) => k.nadir === kn).map((k) => k.id), bugun + "k"); const kk = kl.find((id) => !(o.kartlar[id] > 0)) || kl[0];
  if (kk) out.push({ slot: 3, tip: "kart", id: kk, nadir: kn, fiyat: Math.round(TAKAS_BEDEL[kn] * 0.85) });
  const pr = rngFor("magaza-p", bugun)(); const pt = pr < 0.45 ? "gumus" : pr < 0.75 ? "altin" : ["kutuphane", "diplomasi", "lab", "kulup", "stil", "guc"][Math.floor(pr * 100) % 6];
  out.push({ slot: 4, tip: "paket", id: pt, nadir: PAKET_TUR[pt].deger >= 5 ? "destansi" : PAKET_TUR[pt].deger >= 4 ? "nadir" : "siradan", fiyat: pt === "gumus" ? 60 : pt === "altin" ? 120 : 150 });
