    dersFetih: Object.values(dersK).filter((D) => D.n >= 3 && D.o === D.n).length, mathOturduOran: mat.n ? Math.floor((mat.o / mat.n) * 100) : 0,
    hataCozulen: (d.hatalar || []).filter((h) => h && h.cozuldu).length, anlatmaSay: (d.anlatmalar || []).length,
    mukemmelGun: mgSirali.length, mukemmelSeriMax: (() => { let m = 0, c = 0, onceki = null; for (const t of mgSirali) { c = onceki && gunFark(t, onceki) === 1 ? c + 1 : 1; m = Math.max(m, c); onceki = t; } return m; })(),
    galibiyet, derbiG, yenilmezMax: yenMax, sampiyonluk: ((d.arsiv || {}).kupalar || []).length, fetihKulup: kol.fetih,
    paketAcilan: o.acilanSay || 0, efsaneCekis, setTamam: kol.setTamam, armaSahip: kol.arma, sozSahip: kol.soz, kozSahip: kol.kozStat,
    ligTerfi: lig.terfi, ligIlk3: lig.ilk3, ligBirinci: lig.birinci, ligMax: lig.enYuksek, yolIstasyon: yol.ist, seviye: sv.seviye,
    sezonTamam, altinBilet,
