  liste.push({ k: KUPA_ID["b-platin"], v: Math.min(acik.size, digerSay), ok: platinOk, oran: Math.min(acik.size, digerSay) / digerSay });
  let puan = 0; for (const id of acik) puan += KUPA_TIER[KUPA_ID[id].tier].puan;
  const seviye = Math.floor(puan / KUPA_SEVIYE_PUAN);
