    const od = premium ? sezonOdulP(ay, k) : sezonOdul(ay, k); al.add(k);
    if (od.tur === "paket") ek.push({ id: `${premium ? "szp" : "sz"}:${ay}:${k}`, tur: od.paket, kaynak: `${premium ? "Altın Bilet" : "Sezon"} · ${k}. kademe`, tarih: bugun });
    else if (od.tur === "jeton") jeton += od.adet;
    else if (od.tur === "guc") guc[od.guc] = (guc[od.guc] || 0) + 1;
