  if (k.tur === "cerceve") return <CerceveHalka id={id} boy={boy * 0.8}><SeviyeRozeti sv={sv} oran={0} boy={boy * 0.5} halka={false} /></CerceveHalka>;
  if (k.tur === "rozet") return <RozetGorsel id={id} boy={boy * 0.6} />;
