/* ── KUTLAMA PARÇACIKLARI ── seviye atlama ve efsane paket için; giyilen kutlama efektine göre ── */
function kutlamaAl(d) { const id = ((d && d.oyun && d.oyun.secili) || {}).kutlama; const k = KOZMETIK[id]; return k && k.tur === "kutlama" ? k : KOZMETIK["ku-konfeti"]; }
function KutlamaParcacik({ k, adet = 54, tuz = "" }) {
  const K = k || KOZMETIK["ku-konfeti"]; const renk = K.renk || ["#fff"];
  const parca = useMemo(() => Array.from({ length: adet }, (_, i) => { const h = hashStr("ku" + tuz + i + K.sekil);
    return { l: h % 100, g: ((h >>> 7) % 80) / 100, s: 2 + ((h >>> 12) % 16) / 10, dx: ((h >>> 16) % 50) - 25, r: ((h >>> 20) % 720) - 360, c: renk[i % renk.length], w: 5 + (h % 6), hh: 8 + ((h >>> 5) % 9) }; }), [adet, tuz, K.sekil]);
  const sekil = (p) => {
    if (K.sekil === "daire" || K.sekil === "kar") return { width: p.w, height: p.w, borderRadius: "50%" };
    if (K.sekil === "yildiz") return { width: p.w + 5, height: p.w + 5, clipPath: "polygon(50% 0,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%)" };
    if (K.sekil === "yaprak" || K.sekil === "tuy") return { width: p.w + 3, height: p.hh + 4, borderRadius: "60% 0" };
    if (K.sekil === "kagit") return { width: p.w + 6, height: p.w + 2, clipPath: "polygon(0 50%,100% 0,70% 100%)" };
    if (K.sekil === "piksel") return { width: 7, height: 7 };
    if (K.sekil === "kivilcim") return { width: 2.5, height: p.hh + 8, borderRadius: 2, boxShadow: `0 0 8px ${p.c}` };
    if (K.sekil === "duman") return { width: 40 + p.w * 4, height: 40 + p.w * 4, borderRadius: "50%", filter: "blur(10px)", opacity: 0.5 };
    return { width: p.w, height: p.hh, borderRadius: 2 };
  };
  return <>{parca.map((p, i) => <span key={i} aria-hidden style={{ position: "absolute", left: `${p.l}%`, top: -24, background: String(p.c).startsWith("var") ? "var(--vurgu)" : p.c, pointerEvents: "none",
    animation: `arKonfeti ${p.s}s ${p.g}s cubic-bezier(.2,.6,.4,1) both`, "--dx": `${p.dx}vw`, "--r": `${p.r}deg`, ...sekil(p) }} />)}</>;
}

