  if (KH_AGAC_SON.k && KH_AGAC_SON.k.every((x, i) => x === anahtar[i])) return KH_AGAC_SON.v;
  const K = khKatalog(); const A = khNesne(d.konuAlt);
  /* konu başına dakika · seans · son seans (seanslarda konuId varsa) */
