/* ══ 2 · PAKET TÜRLERİ · 15'ten ~170'e ══ */
const PT = (id, o) => { if (!PAKET_TUR[id]) PAKET_TUR[id] = { deger: 4, ik: "paket", ...o, v72: true }; };
