const koyu = (h, f = 0.28) => { const n = parseInt(h.slice(1), 16); const r = ((n >> 16) & 255) * f, g = ((n >> 8) & 255) * f, b = (n & 255) * f; return "#" + [r, g, b].map((x) => Math.round(x).toString(16).padStart(2, "0")).join(""); };
