  const saat = dk / 60, ist = yi, sonraki = YOL2[ist] || null, onceki = ist ? YOL2[ist - 1].saat : 0;
  const oran = sonraki ? clamp((saat - onceki) / (sonraki.saat - onceki), 0, 1) : 1;
  let son14 = 0; for (let i = 0; i < 14; i++) { const g = sa.gun[addDays(bugun, -i)]; if (g) son14 += g.dkG != null ? g.dkG : g.dk; }
  const tempo = son14 / 14;
