  for (const g of Object.values(G)) { g.rag = Math.min(g.rag, 60); g.yesil = Math.min(g.yesil, 30); g.vade = Math.min(g.vade, 60); }
  for (const a of d.anlatmalar || []) if (a && a.tarih) al(a.tarih).anlatma++;
