  ETK_ODUL.forEach((O, i) => { if (et.seviye > i && O.paket) out.push({ id: `etp:${et.w}:${i}`, tur: O.paket === "e" ? "e-" + et.E.id : O.paket, kaynak: `${et.E.ad} · ${ETK_ESIK[i]} jeton`, tarih: et.w }); });
