        {["rutin", "uyku"].includes(sekme) && <RutinPaneli {...p}
          baslangicSek={sekme === "uyku" ? "uyku" : "aliskanlik"} />}
        {["kitaplik", "kaynakca", "kelime", "yazi"].includes(sekme) && <AkademiPaneli {...p}
          baslangicSek={{ kitaplik: "kitap", kaynakca: "kaynak", kelime: "kelime", yazi: "yazi" }[sekme]} />}
        {sekme === "konu" && <KonuHaritasi {...p} altSekme={altSekme} />}
        {sekme === "anlatma" && <AnlatmaPaneli key={"anl-" + (altSekme || "")} {...p} baslangicKonu={altSekme || null} />}
        {sekme === "dunya" && <DunyaMasasi {...p} />}
