      {/* ── burun ── */}
      <path d={`M${31.6} 29.4 q-0.5 ${y.burunUzun * 0.55} -0.9 ${y.burunUzun}`} stroke={tSh} strokeOpacity="0.30" strokeWidth="1.5" fill="none" strokeLinecap="round" />
