        if (S === "cene") return <path d={sivri} fill={col} opacity="0.88" />;
        if (S === "keci") return <><path d={biyik} fill={col} opacity="0.9" /><path d={sivri} fill={col} opacity="0.88" /></>;
        if (S === "favori") return <><path d={`M${32 - kw + 0.6} 27 q1.3 6 0.6 9.6 q-2.4 -0.6 -2.8 -9.2 Z`} fill={col} opacity="0.8" />
          <path d={`M${32 + kw - 0.6} 27 q-1.3 6 -0.6 9.6 q2.4 -0.6 2.8 -9.2 Z`} fill={col} opacity="0.8" /></>;
