          {/* tel dokusu */}
          {y.sac !== "kivircik" && [0, 1, 2, 3, 4, 5, 6].map((i) => { const dx = -kw * 0.82 + i * (kw * 1.64 / 6);
            return <path key={i} d={`M${32 + dx} ${tepe + 1.6 + Math.abs(dx) * 0.22} q${dx * 0.22} ${(alt - tepe) * 0.55} ${dx * 0.30} ${alt - tepe - 1}`}
              stroke={sHi} strokeOpacity="0.20" strokeWidth="0.7" fill="none" strokeLinecap="round" />; })}
          {/* parlaklık bandı */}
          <ellipse cx={32 - kw * 0.36} cy={tepe + 5.4} rx={kw * 0.40} ry="2.9" fill={sHi} opacity="0.34"
            transform={`rotate(-18 ${32 - kw * 0.36} ${tepe + 5.4})`} />
