/* Türkçe harfleri sadeleştir — "muz" yazınca "Müze" bulunsun */
const trSade = (x) => (x || "").toLocaleLowerCase("tr")
  .replace(/ı/g, "i").replace(/ğ/g, "g").replace(/ü/g, "u").replace(/ş/g, "s").replace(/ö/g, "o").replace(/ç/g, "c").replace(/â/g, "a");
const bulanik = (metin, sorgu) => {
  const m = trSade(metin), q = trSade(sorgu).trim();
  if (!q) return 1;
  if (m.startsWith(q)) return 100;
  if (m.includes(q)) return 60;
  let i = 0, p2 = 0;                                    /* harf sırası eşleşmesi */
  for (const c of q) { const k = m.indexOf(c, i); if (k < 0) return 0; p2 += k === i ? 3 : 1; i = k + 1; }
  return p2 / q.length;
};
