  const akis = useRef(null);
  const onizleme1 = useMemo(() => (fx ? macOyna(d, fx, db.tarih, "sakin") : null), [d, fx, db]);
  const anlati = useMemo(() => { const m = sonMac || onizleme1; return m ? macAnlati(d, m, bugun) : []; }, [sonMac, onizleme1, d, bugun]);
  const gosterMac = sonMac || onizleme1;
  const sinir = faz === "ilk" ? 45 : 90;
  useEffect(() => { if (durdu || faz === "devre" || faz === "bitti") return;
    const iv = setInterval(() => setDk((x) => { if (x >= sinir) return x; return Math.round((x + 0.25) * 4) / 4; }), Math.max(70, 240 / hiz));
    return () => clearInterval(iv); }, [durdu, hiz, sinir, faz]);
  useEffect(() => { if (dk >= 45 && faz === "ilk") setFaz("devre");
    if (dk >= 90 && faz === "ikinci") setFaz("bitti"); }, [dk, faz]);
