      if (o.tip === "gol") Ses.cal(o.biz ? "golBiz" : "golRakip");
      else if (o.tip === "direk") Ses.cal("direk");
      else if (o.tip === "pozisyon") Ses.cal("pozisyon");
      else if (o.tip === "kart") Ses.cal("kart");
      else if (o.tip === "sakat") Ses.cal("uyari");
      else if (o.tip === "durum" && Math.abs(o.mom || 0) > 22) Ses.cal("baski");
      else if (o.tip === "devre") Ses.cal("dudukSon");
